"use client";

import {
  useMemo,
  useState,
  useEffect,
  useCallback,
  useRef,
  createContext,
  useContext,
  forwardRef,
  useImperativeHandle,
  startTransition,
} from "react";
import {
  Autocomplete,
  TextField,
  Checkbox,
  Chip,
  ListItemButton,
  ListItemText,
  Box,
  Paper,
  InputAdornment,
} from "@mui/material";
import type { PaperProps } from "@mui/material";
import { MdSearch, MdClose, MdExpandMore, MdChevronRight } from "react-icons/md";
import { useMT5GroupByServerId } from "@/hooks/MT5/Group/useMT5Group";
import { useCurrentServer } from "@/hooks/useCurrentServerId";
import { validateQueryLength, MAX_QUERY_LENGTH } from "@/utils/string";

// ─── Types ──────────────────────────────────────────────────────────

export interface MT5GroupSelectHandle {
  validate: () => boolean;
}

interface MT5GroupSelectProps {
  value: string | null;
  onChange: (value: string | null) => void;
  label?: string;
  size?: "small" | "medium";
  disabled?: boolean;
  /** Hide the group tree dropdown, allowing free-text input only (e.g. login search) */
  hideOptions?: boolean;
}

interface GroupNode {
  id: string;
  name: string; // Last segment (e.g. "forex-hedge-usd-02")
  path: string; // Full path (e.g. "demo\\forex-hedge-usd-02")
  children: GroupNode[];
  level: number;
  isLeaf: boolean; // true = actual groupName from API
  leafCount: number; // Cached count of leaf groups in this subtree
  isGroup: true;
}

// ─── Search Paper (stable component — never re-mounts) ─────────────

interface SearchPaperContextValue {
  searchText: string;
  onSearchChange: (text: string) => void;
}

const SearchPaperCtx = createContext<SearchPaperContextValue>({
  searchText: "",
  onSearchChange: () => {},
});

function SearchPaper(props: PaperProps) {
  const { searchText, onSearchChange } = useContext(SearchPaperCtx);
  const inputRef = useRef<HTMLInputElement>(null);

  // Auto-focus once when the Paper mounts
  useEffect(() => {
    // setTimeout lets MUI finish positioning the popper before we steal focus
    const id = setTimeout(() => inputRef.current?.focus(), 0);
    return () => clearTimeout(id);
  }, []);

  return (
    <Paper {...props}>
      <Box
        sx={{
          p: 1,
          position: "sticky",
          top: 0,
          zIndex: 1,
          bgcolor: "background.paper",
          borderBottom: "1px solid",
          borderColor: "divider",
        }}
        onMouseDown={e => {
          // Prevent Autocomplete from closing, but allow clicks on the input itself
          if ((e.target as HTMLElement).tagName !== "INPUT") {
            e.preventDefault();
          }
        }}
      >
        <TextField
          inputRef={inputRef}
          size="small"
          fullWidth
          placeholder="Search groups…"
          value={searchText}
          onChange={e => onSearchChange(e.target.value)}
          onKeyDown={e => e.stopPropagation()}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <MdSearch />
              </InputAdornment>
            ),
            endAdornment: searchText ? (
              <InputAdornment position="end">
                <Box
                  component="span"
                  sx={{ cursor: "pointer", display: "flex", alignItems: "center" }}
                  onClick={() => onSearchChange("")}
                >
                  <MdClose />
                </Box>
              </InputAdornment>
            ) : null,
          }}
        />
      </Box>
      {props.children}
    </Paper>
  );
}

// ─── Tree building ──────────────────────────────────────────────────

function buildGroupTree(groupNames: string[]) {
  const nodeMap = new Map<string, GroupNode>();

  // Create nodes for every path segment
  for (const fullName of groupNames) {
    const parts = fullName.split("\\").filter(Boolean);
    for (let i = 1; i <= parts.length; i++) {
      const path = parts.slice(0, i).join("\\");
      if (!nodeMap.has(path)) {
        nodeMap.set(path, {
          id: `group_${path}`,
          name: parts[i - 1],
          path,
          children: [],
          level: i - 1,
          isLeaf: i === parts.length,
          leafCount: 0,
          isGroup: true,
        });
      } else if (i === parts.length) {
        // Mark as leaf if this is an actual group name
        nodeMap.get(path)!.isLeaf = true;
      }
    }
  }

  // Build parent-child relationships
  const allNodes = Array.from(nodeMap.values());
  for (const node of allNodes) {
    const parts = node.path.split("\\");
    if (parts.length > 1) {
      const parentPath = parts.slice(0, -1).join("\\");
      const parent = nodeMap.get(parentPath);
      if (parent && !parent.children.includes(node)) {
        parent.children.push(node);
      }
    }
  }

  // Sort: folders first, then alphabetically
  const sortNodes = (a: GroupNode, b: GroupNode) => {
    const aHasChildren = a.children.length > 0 ? 0 : 1;
    const bHasChildren = b.children.length > 0 ? 0 : 1;
    if (aHasChildren !== bHasChildren) return aHasChildren - bHasChildren;
    return a.name.localeCompare(b.name);
  };
  for (const node of allNodes) {
    node.children.sort(sortNodes);
  }

  // Cache leaf counts (bottom-up)
  const calcLeafCount = (node: GroupNode): number => {
    let count = node.isLeaf ? 1 : 0;
    for (const child of node.children) count += calcLeafCount(child);
    node.leafCount = count;
    return count;
  };

  const roots = allNodes.filter(n => n.level === 0).sort(sortNodes);
  roots.forEach(calcLeafCount);

  return { nodeMap, allNodes, roots };
}

// ─── Component ──────────────────────────────────────────────────────

const MT5GroupSelect = forwardRef<MT5GroupSelectHandle, MT5GroupSelectProps>(
  function MT5GroupSelect(
    {
      value,
      onChange,
      label = "Group, Accounts, or #Orders",
      size = "small",
      disabled = false,
      hideOptions = false,
    },
    ref
  ) {
    const currentServerId = useCurrentServer();
    const { data: groupData, isLoading } = useMT5GroupByServerId({ serverId: currentServerId });
    const [error, setError] = useState(false);
    const [inputValue, setInputValue] = useState("");
    const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());
    const [selectedPaths, setSelectedPaths] = useState<Set<string>>(new Set());
    const [open, setOpen] = useState(false);
    const [searchText, setSearchText] = useState("");
    const [debouncedSearch, setDebouncedSearch] = useState("");
    const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    const handleSearchChange = useCallback((text: string) => {
      setSearchText(text);
      if (debounceRef.current) clearTimeout(debounceRef.current);
      debounceRef.current = setTimeout(() => {
        startTransition(() => setDebouncedSearch(text));
      }, 300);
    }, []);

    const groupNames = useMemo(
      () => (groupData ?? []).map(g => g.groupName).sort((a, b) => a.localeCompare(b)),
      [groupData]
    );
    const { nodeMap, allNodes, roots } = useMemo(() => buildGroupTree(groupNames), [groupNames]);

    // Sync from parent value — separate tree paths from free text
    useEffect(() => {
      if (!value) {
        setSelectedPaths(new Set());
        setInputValue("");
        return;
      }
      const parts = value
        .split(",")
        .map(s => s.trim())
        .filter(Boolean);
      const treePaths = new Set<string>();
      const freeTexts: string[] = [];
      for (const p of parts) {
        // Check if this is a known tree path or wildcard
        const isWildcard = p.endsWith("\\*");
        const basePath = isWildcard ? p.slice(0, -2) : p;
        if (nodeMap.has(basePath) || nodeMap.has(p)) {
          treePaths.add(p);
        } else {
          freeTexts.push(p);
        }
      }
      setSelectedPaths(treePaths);
      setInputValue(freeTexts.join(", "));
    }, [value, nodeMap]);

    // All nodes flattened (stable, never changes on expand/collapse)
    const allFlatOptions = useMemo(() => {
      const opts: GroupNode[] = [];
      const walk = (node: GroupNode) => {
        opts.push(node);
        node.children.forEach(walk);
      };
      roots.forEach(walk);
      return opts;
    }, [roots]);

    // Pre-compute which paths match the search and their ancestors (O(1) lookup)
    const searchVisiblePaths = useMemo(() => {
      const keyword = debouncedSearch.trim().toLowerCase();
      if (!keyword) return null; // null = no search active
      const matched = new Set<string>();
      for (const node of allNodes) {
        if (node.name.toLowerCase().includes(keyword)) {
          // Add matched node + all ancestors
          matched.add(node.path);
          const parts = node.path.split("\\");
          for (let i = 1; i < parts.length; i++) {
            matched.add(parts.slice(0, i).join("\\"));
          }
        }
      }
      return matched;
    }, [debouncedSearch, allNodes]);

    // Auto-expand ancestors of matched nodes during search
    const searchExpandedPaths = useMemo(() => {
      if (!searchVisiblePaths) return null;
      const expanded = new Set<string>();
      Array.from(searchVisiblePaths).forEach(path => {
        const node = nodeMap.get(path);
        if (node && node.children.length > 0) expanded.add(path);
      });
      return expanded;
    }, [searchVisiblePaths, nodeMap]);

    // Visibility: search mode uses pre-computed Set, normal mode checks expanded ancestors
    const isNodeVisible = useCallback(
      (node: GroupNode): boolean => {
        if (searchVisiblePaths) {
          if (!searchVisiblePaths.has(node.path)) return false;
          // Still respect expand/collapse within search results
          if (node.level === 0) return true;
          const parts = node.path.split("\\");
          for (let i = 1; i < parts.length; i++) {
            const ancestorPath = parts.slice(0, i).join("\\");
            if (!searchExpandedPaths?.has(ancestorPath)) return false;
          }
          return true;
        }
        if (node.level === 0) return true;
        const parts = node.path.split("\\");
        for (let i = 1; i < parts.length; i++) {
          const ancestorPath = parts.slice(0, i).join("\\");
          if (!expandedGroups.has(ancestorPath)) return false;
        }
        return true;
      },
      [expandedGroups, searchVisiblePaths, searchExpandedPaths]
    );

    // No filtering — always show full tree, input is for free typing only
    const filterOptions = useCallback((options: GroupNode[]) => options, []);

    // ─── Selection helpers ────────────────────────────────────────

    const isNodeSelected = useCallback(
      (path: string): boolean => {
        // Direct match
        if (selectedPaths.has(path)) return true;
        // Check if any parent wildcard covers it
        const parts = path.split("\\");
        for (let i = 1; i < parts.length; i++) {
          const parentWild = parts.slice(0, i).join("\\") + "\\*";
          if (selectedPaths.has(parentWild)) return true;
        }
        return false;
      },
      [selectedPaths]
    );

    const isNodePartial = useCallback(
      (node: GroupNode): boolean => {
        if (isNodeSelected(node.path)) return false;
        if (selectedPaths.has(node.path + "\\*")) return false;
        // Check if any descendant is selected
        const checkDescendants = (n: GroupNode): boolean => {
          if (n.isLeaf && isNodeSelected(n.path)) return true;
          if (selectedPaths.has(n.path + "\\*")) return true;
          return n.children.some(checkDescendants);
        };
        return node.children.some(checkDescendants);
      },
      [selectedPaths, isNodeSelected]
    );

    // ─── Emit combined value (tree selections + free text) ─────────
    const buildOutputValue = useCallback(
      (paths: Set<string>, freeText?: string) => {
        const parts: string[] = Array.from(paths);
        const text = (freeText ?? inputValue).trim();
        if (text) {
          // Add comma-separated free text parts that aren't already in tree selections
          text
            .split(",")
            .map(s => s.trim())
            .filter(Boolean)
            .forEach(s => {
              if (!parts.includes(s)) parts.push(s);
            });
        }
        return parts.length > 0 ? parts.join(",") : null;
      },
      [inputValue]
    );

    const emitValue = useCallback(
      (paths: Set<string>) => {
        const outputValue = buildOutputValue(paths);

        // Validate length before emitting
        if (!validateQueryLength(outputValue, "Group search query")) return;

        setSelectedPaths(paths);
        setError(false);
        onChange(outputValue);
      },
      [onChange, buildOutputValue]
    );

    // ─── Toggle folder / leaf ─────────────────────────────────────
    const handleNodeToggle = useCallback(
      (node: GroupNode) => {
        const newPaths = new Set(selectedPaths);

        if (node.children.length > 0) {
          // Folder node: toggle wildcard
          const wildcard = node.path + "\\*";
          if (selectedPaths.has(wildcard) || isNodeSelected(node.path)) {
            // Deselect: remove wildcard and all descendants
            newPaths.delete(wildcard);
            newPaths.delete(node.path);
            const removeDescendants = (n: GroupNode) => {
              newPaths.delete(n.path);
              newPaths.delete(n.path + "\\*");
              n.children.forEach(removeDescendants);
            };
            removeDescendants(node);
          } else {
            // Select: add wildcard, remove individual descendants
            const removeDescendants = (n: GroupNode) => {
              newPaths.delete(n.path);
              newPaths.delete(n.path + "\\*");
              n.children.forEach(removeDescendants);
            };
            removeDescendants(node);
            newPaths.add(wildcard);
          }
        } else {
          // Leaf node: toggle individual
          if (isNodeSelected(node.path)) {
            newPaths.delete(node.path);
            // If was covered by parent wildcard, expand parent
            const parts = node.path.split("\\");
            for (let i = parts.length - 1; i >= 1; i--) {
              const parentWild = parts.slice(0, i).join("\\") + "\\*";
              if (newPaths.has(parentWild)) {
                newPaths.delete(parentWild);
                // Add siblings
                const parentNode = nodeMap.get(parts.slice(0, i).join("\\"));
                if (parentNode) {
                  const addSiblings = (n: GroupNode) => {
                    if (n.isLeaf && n.path !== node.path) newPaths.add(n.path);
                    if (n.children.length > 0 && n.path !== node.path) {
                      newPaths.add(n.path + "\\*");
                    }
                  };
                  parentNode.children.forEach(addSiblings);
                  // Add parent's own leaf status
                  if (parentNode.isLeaf && parentNode.path !== node.path) {
                    newPaths.add(parentNode.path);
                  }
                }
                break;
              }
            }
          } else {
            newPaths.add(node.path);
          }
        }

        emitValue(newPaths);
      },
      [selectedPaths, isNodeSelected, nodeMap, emitValue]
    );

    const toggleExpand = useCallback((path: string) => {
      startTransition(() => {
        setExpandedGroups(prev => {
          const next = new Set(prev);
          if (next.has(path)) next.delete(path);
          else next.add(path);
          return next;
        });
      });
    }, []);

    // ─── Selected options for tags ────────────────────────────────
    const selectedOptions = useMemo(() => {
      return allFlatOptions.filter(o => {
        if (selectedPaths.has(o.path)) return true;
        if (selectedPaths.has(o.path + "\\*")) return true;
        return false;
      });
    }, [selectedPaths, allFlatOptions]);

    // ─── Validate ─────────────────────────────────────────────────
    useImperativeHandle(ref, () => ({
      validate: () => {
        const combined = buildOutputValue(selectedPaths);
        if (combined && combined.trim() !== "*") {
          setError(false);
          onChange(combined);
          return true;
        }
        setError(true);
        return false;
      },
    }));

    // ─── Selection state cache ────────────────────────────────────
    const selectionCache = useMemo(() => {
      const cache = new Map<string, { selected: boolean; partial: boolean }>();
      for (const node of allNodes) {
        cache.set(node.path, {
          selected: isNodeSelected(node.path) || selectedPaths.has(node.path + "\\*"),
          partial: isNodePartial(node),
        });
      }
      return cache;
    }, [allNodes, isNodeSelected, isNodePartial, selectedPaths]);

    // ─── Context value for SearchPaper (stable identity via useMemo) ──
    const searchCtxValue = useMemo(
      () => ({ searchText, onSearchChange: handleSearchChange }),
      [searchText, handleSearchChange]
    );

    return (
      <SearchPaperCtx.Provider value={searchCtxValue}>
      <Autocomplete
        multiple
        open={hideOptions ? false : open}
        onOpen={() => {
          if (!hideOptions) setOpen(true);
        }}
        onClose={() => {
          setOpen(false);
          handleSearchChange("");
        }}
        options={hideOptions ? [] : allFlatOptions}
        value={selectedOptions}
        inputValue=""
        onInputChange={() => {
          // Input controlled separately to avoid listbox re-render on typing
        }}
        onChange={(_e, _val, reason) => {
          // Handle clear button
          if (reason === "clear") {
            setSelectedPaths(new Set());
            setInputValue("");
            onChange(null);
          }
          // Other changes handled by handleNodeToggle
        }}
        filterOptions={filterOptions}
        loading={isLoading}
        disabled={disabled}
        disableCloseOnSelect
        size={size}
        fullWidth
        freeSolo
        forcePopupIcon={false}
        getOptionKey={o => (typeof o === "string" ? o : o.id)}
        getOptionLabel={o => (typeof o === "string" ? o : o.path)}
        isOptionEqualToValue={(opt, val) => {
          if (typeof opt === "string" || typeof val === "string") return opt === val;
          return opt.path === val.path;
        }}
        renderOption={(props, option) => {
          if (typeof option === "string") return null;
          const { key } = props;
          const node = option;
          if (!isNodeVisible(node)) return null;
          const hasChildren = node.children.length > 0;
          const expanded = expandedGroups.has(node.path);
          const state = selectionCache.get(node.path);
          const checked = state?.selected ?? false;
          const indeterminate = state?.partial ?? false;

          return (
            <ListItemButton
              key={key}
              disableRipple
              onClick={(e: React.MouseEvent) => {
                e.stopPropagation();
                if (hasChildren) toggleExpand(node.path);
                else handleNodeToggle(node);
              }}
              sx={{ pl: node.level * 2 + 2, py: 0 }}
            >
              {hasChildren ? (
                expanded ? (
                  <MdExpandMore />
                ) : (
                  <MdChevronRight />
                )
              ) : (
                <Box sx={{ width: 24 }} />
              )}
              <Checkbox
                checked={checked}
                indeterminate={indeterminate}
                disableRipple
                onClick={(e: React.MouseEvent) => {
                  e.stopPropagation();
                  handleNodeToggle(node);
                }}
                sx={{ mr: 1 }}
              />
              <ListItemText
                primary={
                  <Box sx={{ display: "inline-flex", alignItems: "center", gap: 0.5 }}>
                    <span>{node.name}</span>
                    {hasChildren && (
                      <Box
                        component="span"
                        sx={{ color: "text.secondary", fontSize: "0.75rem", ml: 0.5 }}
                      >
                        ({node.leafCount})
                      </Box>
                    )}
                  </Box>
                }
                slotProps={{
                  primary: {
                    sx: { fontWeight: hasChildren ? 500 : 400, fontSize: "0.875rem" },
                  },
                }}
              />
            </ListItemButton>
          );
        }}
        renderTags={() => {
          const displayPaths = Array.from(selectedPaths);
          if (displayPaths.length === 0 && value) {
            return (
              <Chip
                label={value}
                size="small"
                onDelete={() => {
                  onChange(null);
                }}
              />
            );
          }
          return displayPaths.map(path => (
            <Chip
              key={path}
              label={path}
              size="small"
              sx={{ mr: 0.5, mb: 0.5 }}
              onDelete={() => {
                const newPaths = new Set(selectedPaths);
                newPaths.delete(path);
                emitValue(newPaths);
              }}
            />
          ));
        }}
        slots={{ paper: SearchPaper }}
        slotProps={{
          listbox: {
            style: { maxHeight: 400 },
          },
        }}
        renderInput={params => (
          <TextField
            {...params}
            label={label}
            sx={{ margin: 0 }}
            error={error}
            placeholder={
              error
                ? "This field is required"
                : !hideOptions && selectedPaths.size === 0
                  ? "Type or select groups"
                  : undefined
            }
            inputProps={{
              ...params.inputProps,
              value: inputValue,
              onChange: (e: React.ChangeEvent<HTMLInputElement>) => {
                const newText = e.target.value;
                // Check combined length (tree selections + new input)
                const combined = buildOutputValue(selectedPaths, newText);
                if (combined && combined.length > MAX_QUERY_LENGTH) return;
                setInputValue(newText);
                if (newText) setError(false);
                if (open) setOpen(false);
              },
            }}
            InputLabelProps={{
              ...params.InputLabelProps,
              shrink:
                error ||
                !!inputValue ||
                selectedPaths.size > 0 ||
                (params.InputLabelProps as { shrink?: boolean })?.shrink,
              sx: { ...(error && { color: "error.main" }) },
            }}
            onKeyDown={e => {
              if (e.key === "Enter") {
                const outputValue = buildOutputValue(selectedPaths);
                if (!validateQueryLength(outputValue, "Group search query")) return;
                setError(false);
                onChange(outputValue);
              }
              // Close panel when user starts typing (printable characters)
              if (open && e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
                setOpen(false);
              }
            }}
            onBlur={() => {
              const outputValue = buildOutputValue(selectedPaths);
              if (!validateQueryLength(outputValue, "Group search query")) return;
              onChange(outputValue);
            }}
          />
        )}
      />
      </SearchPaperCtx.Provider>
    );
  }
);

export default MT5GroupSelect;

"use client";

import { useState, useEffect, useMemo } from "react";
import {
  Box,
  Button,
  CircularProgress,
  Chip,
  Dialog,
  DialogContent,
  DialogTitle,
  IconButton,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
  useTheme,
} from "@mui/material";
import { MdClose } from "react-icons/md";
import { CheckCircle, Cancel, Replay } from "@mui/icons-material";
import { useApprovalTaskById } from "@/hooks/GlobalModule/useApprovalTasks";
import { formatDateTime } from "@/utils/date";
import { IApprovalJournal, IApprovalLog } from "@/types/GlobalModule/approvalTask";
import ApprovalStepper from "../components/ApprovalStepper";
import { useApprovalAction } from "@/hooks/GlobalModule/useApprovalAction";
import { useSession } from "next-auth/react";
import type { ISessionUserInformation } from "@/types/userManagement";

// Only tasks with these journal result codes can perform actions
// 1 = AwaitingApproval
const ACTIONABLE_JOURNAL_RESULTS = [1];

interface ApprovalTaskModalProps {
  taskId: number;
  open: boolean;
  onClose: () => void;
  /** Check if user has approval permission for a specific server and risk level */
  checkApprovalPermission?: (serverName: string, moduleName: string, riskLevel: number) => boolean;
}

export default function ApprovalTaskModal({
  taskId,
  open,
  onClose,
  checkApprovalPermission,
}: ApprovalTaskModalProps) {
  const theme = useTheme();
  const { openApprove, openReject, openRecall } = useApprovalAction();

  // Get current user for permission checks
  const { data: session } = useSession();
  const currentUser = session?.user as ISessionUserInformation | undefined;
  const currentUserEmail = currentUser?.email;

  const { data: taskData, isLoading } = useApprovalTaskById({
    taskId,
    enabled: open && taskId !== null,
  });

  // Parse targets and track which one is active
  const targets = useMemo(
    () => (taskData?.target ? taskData.target.split(",") : []),
    [taskData?.target]
  );
  const [activeTarget, setActiveTarget] = useState<string>("");

  // Reset activeTarget when taskData changes (e.g. opening a different task)
  useEffect(() => {
    if (targets.length > 0 && !targets.includes(activeTarget)) {
      setActiveTarget(targets[0]);
    }
  }, [targets]);

  // Check if actions are allowed based on the latest journal result
  const journals = taskData?.approvalJournals || [];
  const sortedJournals = [...journals].sort((a, b) => a.step - b.step);
  const latestJournal = sortedJournals[sortedJournals.length - 1];
  const isActionable = latestJournal
    ? ACTIONABLE_JOURNAL_RESULTS.includes(latestJournal.result)
    : false;

  // Check if the current user is the submitter (for Recall action)
  const isSubmittedByCurrentUser =
    currentUserEmail &&
    taskData?.submittedBy &&
    currentUserEmail.toLowerCase() === taskData.submittedBy.toLowerCase();

  // Check permission based on target server and risk level
  // riskLevel: 1 = HighRisk (needs "Approve for High" on the target server)
  // riskLevel: 2 = MediumRisk (needs "Approve for Medium" on the target server)
  const hasApprovePermission =
    !isSubmittedByCurrentUser &&
    checkApprovalPermission &&
