function formatHeaderSuffix(
  treeData: IMT5TicketTreeFlatResponse,
  ticketType: MT5EntityType,
  ticket: number
): string {
  if (ticketType === "deal") {
    const deal = treeData.deals.find(d => d.deal === ticket);
    if (!deal) return "";
    if (getDealActionCategory(deal.action) === "buy_sell") {
      return `${deal.action.toLowerCase()} ${deal.volume} ${deal.symbol} ${deal.price}`;
    }
    const comment = deal.comment ? ` [${deal.comment}]` : "";
    return `${deal.action.toLowerCase()} ${deal.profit.toFixed(2)}${comment}`;
  }

  if (ticketType === "order") {
    const order = treeData.orders.find(o => o.order === ticket);
    if (!order) return "";
    return `${order.type} ${order.volume} ${order.symbol} at ${order.priceOrder}`;
  }

  if (ticketType === "position") {
    const position = treeData.positions.find(p => p.positionTicket === ticket);
    if (!position) return "";
    return `${position.action.toLowerCase()} ${position.volume} ${position.symbol} ${position.priceOpen}`;
  }

  return "";
}

function getEnumLabel(items: IEnumItem[] | undefined, key: number): string | undefined {
  return items?.find(e => e.key === key)?.label;
}

function formatHeaderSuffixFromDetail(
  entityType: MT5EntityType,
  orderDetail: IMT5OrderDetail | undefined,
  dealDetail: IMT5DealDetail | undefined,
  posDetail: IMT5PositionDetail | undefined,
  orderEnums: IMT5OrderEnumData | undefined,
  posEnums: IMT5PositionEnumData | undefined,
  dealEnums: IMT5DealEnumData | undefined
): string {
  if (entityType === "order" && orderDetail) {
    const typeLabel = getEnumLabel(orderEnums?.type, orderDetail.type) ?? String(orderDetail.type);
    return `${typeLabel} ${orderDetail.volumeInitialInLots} ${orderDetail.symbol} at ${orderDetail.priceOrder}`;
  }
  if (entityType === "deal" && dealDetail) {
    const actionLabel =
      getEnumLabel(dealEnums?.action, dealDetail.action) ?? String(dealDetail.action);
    if (getDealActionCategory(dealDetail.action) === "buy_sell") {
      return `${actionLabel.toLowerCase()} ${dealDetail.volume} ${dealDetail.symbol} ${dealDetail.price}`;
    }
    const comment = dealDetail.comment ? ` [${dealDetail.comment}]` : "";
    return `${actionLabel.toLowerCase()} ${dealDetail.profit.toFixed(2)}${comment}`;
  }
  if (entityType === "position" && posDetail) {
    const actionLabel =
      getEnumLabel(posEnums?.action, posDetail.action) ?? String(posDetail.action);
    return `${actionLabel.toLowerCase()} ${posDetail.volumeInLots} ${posDetail.symbol} ${posDetail.priceOpen}`;
  }
  return "";
}

function getSchemaAndDefaults(entityType: MT5EntityType) {
  switch (entityType) {
    case "position":
      return {
        schema: getMT5PositionValidationSchema(),
        defaults: DEFAULT_MT5_POSITION_FORM_VALUES,
      };
    case "order":
      return { schema: getMT5OrderValidationSchema(), defaults: DEFAULT_MT5_ORDER_FORM_VALUES };
    case "deal":
      return { schema: getMT5DealValidationSchema(), defaults: DEFAULT_MT5_DEAL_FORM_VALUES };
  }
}

// ─── Component ──────────────────────────────────────────────────────

const SUB_PAGE_LABELS: Record<string, string> = {
  positions: "Position",
  orders: "Order",
  deals: "Deal",
};

export default function MT5OrderModal() {
  const serverId = useCurrentServer();
  const pathname = usePathname();
  const { currentServer: currentServerName } = useAppNavigation();
  const { hasPermissionNew, isLoading: isLoadingPermissions, getFieldRiskLevel } = usePermissions();
  const canReopen = hasPermissionNew("mt5", "Order", "Reopen");
  const canToHistory = hasPermissionNew("mt5", "Order", "To History");
  const canReport = hasPermissionNew("mt5", "Order", "Report");

  // Derive label from URL path segment (e.g. /orders/positions → "Position")
  const subPageSegment = pathname.split("/orders/")[1]?.split(/[/?#]/)[0] ?? "";
  const subPageLabel = SUB_PAGE_LABELS[subPageSegment] ?? "Order";
  const { isOpen, entityType, entityId, login, selectedTab, closeModal, setTab, switchEntity } =
    useMT5OrderModal();
  const queryClient = useQueryClient();

  const invalidateEntityQueries = useCallback(() => {
    orchestrator.refetch();
    if (entityType === "order") {
      queryClient.invalidateQueries({ queryKey: [MT5_ORDER_LIST_KEY] });
      queryClient.removeQueries({ queryKey: ["mt5OrderDetail"] });
    } else if (entityType === "position") {
      queryClient.invalidateQueries({ queryKey: [MT5_POSITION_LIST_KEY] });
      queryClient.removeQueries({ queryKey: ["mt5PositionDetail"] });
    } else if (entityType === "deal") {
      queryClient.invalidateQueries({ queryKey: [MT5_DEAL_LIST_KEY] });
      queryClient.removeQueries({ queryKey: ["mt5DealDetail"] });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- orchestrator.refetch is stable via useCallback
  }, [entityType, queryClient]);

  // ─── Deal Detail API (hoisted so tree-chain gate can read action category) ──
  // Non-trade deals (BALANCE, CREDIT, etc.) have no associated position, so
  // we skip the tree chain entirely and synthesise a single-row tree from detail.
  const {
    data: dealDetailData,
    isFetching: isDealDetailFetching,
    refetch: refetchDeal,
  } = useMT5DealDetail({
    serverId: serverId ?? 0,
    dealTicket: entityId ?? 0,
    enabled: isOpen && entityType === "deal" && !!serverId && !!entityId,
  });

  // ─── Tree API (chain: resolve → position → deals → orders) ──
  // Tree params fire immediately on open for every entity type — the resolve
  // call decides whether a parent position exists. When positionTicket === 0
  // the chain short-circuits and we render a synth row from detail instead.
  const treeParamsRef = useRef<{
    serverId: number;
    ticket: number;
    ticketType: MT5EntityType;
    login?: number;
  } | null>(null);
  if (!isOpen) treeParamsRef.current = null;
  const canInitTreeParams =
    isOpen && !!serverId && !!entityType && !!entityId && !treeParamsRef.current;
  if (canInitTreeParams) {
    treeParamsRef.current = {
      serverId: serverId!,
      ticket: entityId!,
      ticketType: entityType!,
      ...(login ? { login } : {}),
    };
  }
  const orchestrator = useMT5TicketTreeOrchestrator(treeParamsRef.current);
  const treeData = orchestrator.treeData;
  const treeError = orchestrator.error;

  // ─── Derived: login from orchestrator (available after resolve), fallback to URL param ──
  // Resolve may return login=0 when positionTicket=0 (orphan order/non-trade deal),
  // so fall back to the entity's detail login for downstream API calls.
  const treeLogin = orchestrator.login || login || dealDetailData?.login || 0;

  // ─── Header: always derived from initial open params ─
  const initialParams = treeParamsRef.current;

  // ─── Tabs: hide Visualization & Ticks — moved below effectiveTreeData ──

  // ─── Account Info API ────────────────────────────────────────────
  const { data: accountInfo, isLoading: isLoadingAccountInfo } = useMT5AccountInfo({
    serverId: serverId ?? 0,
    login: treeLogin,
    enabled: isOpen && !!serverId && !!treeLogin,
  });

  // ─── Symbol Data (for SymbolTreeSelect in Deal details) ──────
  const { data: symbols, isLoading: isLoadingSymbols } = useMT5Symbols({
    serverId: serverId ?? undefined,
    enabled: isOpen && !!serverId,
  });

  // ─── Enum API ────────────────────────────────────────────────────
  const { data: enumData } = useCommonEnum<IMT5OrderEnumData>({
    version: 5,
    module: MODULES.ORDERS,
    enabled: isOpen,
  });
  const { data: positionEnumData } = useCommonEnum<IMT5PositionEnumData>({
    version: 5,
    module: MODULES.POSITION,
    enabled: isOpen,
  });
  const { data: dealEnumData } = useCommonEnum<IMT5DealEnumData>({
    version: 5,
    module: MODULES.DEAL,
    enabled: isOpen,
  });

  // ─── Detail APIs (fetch when an entity is selected in the tree) ──
  const {
    data: orderDetailData,
    isFetching: isOrderDetailFetching,
    refetch: refetchOrder,
  } = useMT5OrderDetail({
    serverId: serverId ?? 0,
    orderTicket: entityId ?? 0,
    enabled: isOpen && entityType === "order" && !!serverId && !!entityId,
  });
  const {
    data: positionDetailData,
    isFetching: isPositionDetailFetching,
    refetch: refetchPosition,
  } = useMT5PositionDetail({
    serverId: serverId ?? 0,
    positionTicket: entityId ?? 0,
    login: treeLogin,
    enabled: isOpen && entityType === "position" && !!serverId && !!entityId && !!treeLogin,
  });

  const isDetailLoading =
    (entityType === "order" && isOrderDetailFetching) ||
    (entityType === "deal" && isDealDetailFetching) ||
    (entityType === "position" && isPositionDetailFetching);

  // ─── Synthetic single-row tree from detail (seeds the table before chain completes) ──
  // Built for every entity type. Merged with chain data below; chain rows win on conflict.
  const syntheticTreeData = useMemo<IMT5TicketTreeFlatResponse | null>(() => {
    if (entityType === "deal" && dealDetailData) {
      return buildSyntheticTreeFromDeal(dealDetailData, dealEnumData);
    }
    if (entityType === "order" && orderDetailData) {
      return buildSyntheticTreeFromOrder(orderDetailData, enumData);
    }
    if (entityType === "position" && positionDetailData) {
      return buildSyntheticTreeFromPosition(positionDetailData, positionEnumData);
    }
    return null;
  }, [
    entityType,
    dealDetailData,
    orderDetailData,
    positionDetailData,
    enumData,
    positionEnumData,
    dealEnumData,
  ]);

  // ─── Merge synthetic detail row into partial tree (progressive render) ──
  const mergedPartialTreeData = useMemo(
    () =>
      syntheticTreeData
        ? mergeDedupeTreeData(syntheticTreeData, orchestrator.partialTreeData)
        : orchestrator.partialTreeData,
    [syntheticTreeData, orchestrator.partialTreeData]
  );

  // ─── Effective tree data (full) — merges synth row into chain response ──
  const effectiveTreeData = useMemo(() => {
    if (syntheticTreeData && treeData) return mergeDedupeTreeData(syntheticTreeData, treeData);
    return syntheticTreeData ?? treeData;
  }, [syntheticTreeData, treeData]);

  // ─── Tabs: hide Visualization & Ticks for certain entity states ──
  // Hide for orders with STARTED/REJECTED state.
  const HIDDEN_TICK_STATES = new Set(["STARTED", "REJECTED"]);
  const currentOrderState =
    entityType === "order" && effectiveTreeData
      ? effectiveTreeData.orders.find(o => o.order === entityId)?.state?.toUpperCase()
      : undefined;
  const hideForOrderState =
    entityType === "order" && !!currentOrderState && HIDDEN_TICK_STATES.has(currentOrderState);

  // Hide for deals whose action is not Buy, Sell, Buy Canceled, or Sell Canceled.
  // Fall back to dealDetailData.action when the tree chain is skipped.
  const currentDealAction =
    entityType === "deal"
      ? (effectiveTreeData?.deals.find(d => d.deal === entityId)?.action ?? dealDetailData?.action)
      : undefined;
  const hideForDealAction =
    entityType === "deal" &&
    !!currentDealAction &&
    getDealActionCategory(currentDealAction) !== "buy_sell";

  const hideTicksTabs = hideForOrderState || hideForDealAction;
  const visibleTabs = useMemo(
    () =>
      hideTicksTabs
        ? ALL_TABS.filter(t => t.value !== "visualization" && t.value !== "ticks")
        : ALL_TABS,
    [hideTicksTabs]
  );

  // Fall back to details if current tab is hidden
  useEffect(() => {
    if (hideTicksTabs && (selectedTab === "visualization" || selectedTab === "ticks")) {
      setTab("details");
    }
  }, [hideTicksTabs, selectedTab, setTab]);

  // ─── Header suffix (from effective tree data, fallback to detail) ─────────
  // Uses effectiveTreeData (synth merged with chain) so the suffix renders even
  // when the resolve chain is short-circuited (no parent position).
  const headerSuffix = useMemo(() => {
    if (effectiveTreeData && initialParams) {
      const suffix = formatHeaderSuffix(
        effectiveTreeData,
        initialParams.ticketType,
        initialParams.ticket
      );
      if (suffix) return suffix;
    }
    return formatHeaderSuffixFromDetail(
      entityType ?? "position",
      orderDetailData,
      dealDetailData,
      positionDetailData,
      enumData,
      positionEnumData,
      dealEnumData
    );
  }, [
    effectiveTreeData,
    initialParams,
    entityType,
    orderDetailData,
    dealDetailData,
    positionDetailData,
    enumData,
    positionEnumData,
    dealEnumData,
  ]);

  // ─── Form ─────────────────────────────────────────────────────────
  const safeEntityType = entityType ?? "position";

  const { schema, defaults } = useMemo(
    () => getSchemaAndDefaults(safeEntityType),
    [safeEntityType]
  );

  const methods = useForm<AnyFormData>({
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    resolver: yupResolver(schema as any),
    defaultValues: defaults,
    mode: "onChange",
  });

  const { reset, handleSubmit, formState } = methods;
  const { isDirty } = formState;
  const isSubmitting = formState.isSubmitting;

  // ─── Update / Compare mutations ─────────────────────────────────
  const compareOrder = useMT5OrderCompare();
  const { mutateAsync: updateOrder, isPending: isUpdating } = useMT5OrderUpdate();
  const comparePosition = useMT5PositionCompare();
  const { mutateAsync: updatePosition, isPending: isUpdatingPosition } = useMT5PositionUpdate();
  const compareDeal = useMT5DealCompare();
  const { mutateAsync: updateDeal, isPending: isUpdatingDeal } = useMT5DealUpdate();

  // ─── Approval mode ──────────────────────────────────────────────
  const { isUnlocked, toggleUnlock, canUnlock, hasApprovalForRiskLevel, permissionDetails } =
    useApprovalMode("Order");

  const approvalWorkflow = useApprovalWorkflow({
    serverType: "mt5",
    module: "Order",
    entityId: entityId?.toString() || undefined,
    serverId: serverId ?? 0,
  });

  const isUpdatingAny = isUpdating || isUpdatingPosition || isUpdatingDeal;

  // Derive pending approval status from the detail API for the active entity
  const isPendingApproval =
    (entityType === "order" && !!orderDetailData?.existsPendingApproval) ||
    (entityType === "position" && !!positionDetailData?.existsPendingApproval) ||
    (entityType === "deal" && !!dealDetailData?.existsPendingApproval);

  const [isRefreshing, setIsRefreshing] = useState(false);
  const [reopenDialogOpen, setReopenDialogOpen] = useState(false);
  const [toHistoryDialogOpen, setToHistoryDialogOpen] = useState(false);
  const [reportModalOpen, setReportModalOpen] = useState(false);
  const [pendingAction, setPendingAction] = useState<"save" | "reopen" | null>(null);
  const [dirtyConfirmAction, setDirtyConfirmAction] = useState<"toHistory" | "reopen" | null>(null);
  const [showSuccessDialog, setShowSuccessDialog] = useState(false);
  const [wasApprovalSubmission, setWasApprovalSubmission] = useState(false);
  const [submittedApprover, setSubmittedApprover] = useState<Approver | null>(null);
  const prevIsOpenRef = useRef(isOpen);

  // ─── Field-level permission check for Order editing ─────────────
  // Matches MT4 pattern: check each field individually against the user's
  // risk-level permissions, then fall back to approval unlock mode.
  const hasPermissionOrder = useCallback(
    <T extends FieldForServerModuleTab<"mt5", "Order", "Details">>(field: T) => {
      if (entityType !== "order") return false;
      if (isSubmitting || isUpdating || isLoadingPermissions) return false;
      if (isPendingApproval) return false;

      const hasUpdatePermission = hasPermissionNew("mt5", "Order", "Details", field);
      if (hasUpdatePermission) return true;

      if (isUnlocked) {
        const riskLevel = getFieldRiskLevel("mt5", "order", `details.${field}`);
        return hasApprovalForRiskLevel(riskLevel);
      }

      return false;
    },
    [
      entityType,
      isSubmitting,
      isUpdating,
      isLoadingPermissions,
      isPendingApproval,
      hasPermissionNew,
      isUnlocked,
      getFieldRiskLevel,
      hasApprovalForRiskLevel,
    ]
  );

  const hasPermissionPosition = useCallback(
    (field: string) => {
      if (entityType !== "position") return false;
      if (isSubmitting || isUpdatingPosition || isLoadingPermissions) return false;
      if (isPendingApproval) return false;
      const treePosition = treeData?.positions.find(p => p.positionTicket === entityId);
      if (treePosition?.isHistory ?? positionDetailData?.isHistory) return false;

      // Get field risk level using "position" (matches mt5_position_details_* in risk data)
      const riskLevel = getFieldRiskLevel("mt5", "position", `details.${field}`);
      const requiredPerm =
        riskLevel !== undefined
          ? REQUIRED_PERMISSION_FOR_RISK_LEVEL[
              riskLevel as keyof typeof REQUIRED_PERMISSION_FOR_RISK_LEVEL
            ]
          : undefined;

      // Check against "Order" category (Position shares Order's permission category)
      if (requiredPerm && hasPermissionNew("mt5", "Order", requiredPerm)) return true;

      // Approval unlock fallback
      if (isUnlocked) {
        return hasApprovalForRiskLevel(riskLevel);
      }

      return false;
    },
    [
      entityType,
      entityId,
      isSubmitting,
      isUpdatingPosition,
      isLoadingPermissions,
      isPendingApproval,
      treeData,
      positionDetailData?.isHistory,
      hasPermissionNew,
      isUnlocked,
      getFieldRiskLevel,
      hasApprovalForRiskLevel,
    ]
  );

  const hasPermissionDeal = useCallback(
    (field: string) => {
      if (entityType !== "deal") return false;
      if (isSubmitting || isUpdatingDeal || isLoadingPermissions) return false;
      if (isPendingApproval) return false;

      const riskLevel = getFieldRiskLevel("mt5", "deal", `details.${field}`);
      const requiredPerm =
        riskLevel !== undefined
          ? REQUIRED_PERMISSION_FOR_RISK_LEVEL[
              riskLevel as keyof typeof REQUIRED_PERMISSION_FOR_RISK_LEVEL
            ]
          : undefined;

      if (requiredPerm && hasPermissionNew("mt5", "Order", requiredPerm)) return true;

      if (isUnlocked) {
        return hasApprovalForRiskLevel(riskLevel);
      }

      return false;
    },
    [
      entityType,
      isSubmitting,
      isUpdatingDeal,
      isLoadingPermissions,
      isPendingApproval,
      hasPermissionNew,
      isUnlocked,
      getFieldRiskLevel,
      hasApprovalForRiskLevel,
    ]
  );

  // ─── Reopen eligibility (only for "order" entity type) ───────────
  const currentOrder =
    entityType === "order" && treeData
      ? treeData.orders.find(o => o.order === entityId)
      : undefined;
  const showReopenButton =
    entityType === "order" && !!currentOrder && !isToHistoryState(currentOrder.state);

  // ─── To History eligibility (only for "order" entity type) ──────
  // Base eligibility (without pending) controls button visibility;
  // full eligibility (with pending) controls disabled state & tooltip.
  const toHistoryBaseEligibility =
    entityType === "order" && currentOrder
      ? getToHistoryEligibility({
          canToHistory,
          isCurrentDatabase: true,
          hasPendingApproval: false,
          orderState: currentOrder.state ?? "",
        })
      : { eligible: false, tooltip: "Only available for orders" };
  const toHistoryFullEligibility =
    entityType === "order" && currentOrder
      ? getToHistoryEligibility({
          canToHistory,
          isCurrentDatabase: true,
          hasPendingApproval: isPendingApproval,
          orderState: currentOrder.state ?? "",
        })
      : { eligible: false, tooltip: "Only available for orders" };
  // Build a minimal IMT5Order shape for the reopen dialog
  const currentOrderForDialog: IMT5Order | undefined = currentOrder
    ? {
        order: currentOrder.order,
        login: currentOrder.login,
        symbol: currentOrder.symbol,
        type: currentOrder.type as unknown as number,
        state: currentOrder.state,
        position: currentOrder.positionID,
        externalID: currentOrder.externalID,
        timeSetup: 0,
        timeDone: 0,
        volumeInitial: 0,
        volumeCurrent: 0,
        openPrice: 0,
        priceOrder: currentOrder.priceOrder,
        priceTrigger: currentOrder.priceTrigger,
        sl: 0,
        priceSL: currentOrder.priceSL,
        tp: 0,
        priceTP: currentOrder.priceTP,
        priceCurrent: currentOrder.priceCurrent,
        reason: currentOrder.reason,
        dealer: currentOrder.dealer,
        timeExpiration: 0,
        comment: currentOrder.comment,
        highlight: false,
        volume: currentOrder.volume,
      }
    : undefined;

  // ─── Handlers ─────────────────────────────────────────────────────
  const handleRefreshData = useCallback(async () => {
    setIsRefreshing(true);
    try {
      // Orchestrator always re-fires resolve; chain short-circuits if positionTicket=0.
      orchestrator.refetch();
      await Promise.all([
        entityType === "order" ? refetchOrder() : Promise.resolve(),
        entityType === "deal" ? refetchDeal() : Promise.resolve(),
        entityType === "position" ? refetchPosition() : Promise.resolve(),
      ]);
    } catch (error) {
      console.error("Failed to refresh data:", error);
    } finally {
      setIsRefreshing(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- orchestrator.refetch is stable via useCallback
  }, [entityType, refetchOrder, refetchDeal, refetchPosition]);

  // ─── Compare → Approval → Update flow ───────────────────────────
  const compareAndOpenModal = useCallback(
    async (action: "save" | "reopen") => {
      if (!orderDetailData || !serverId) return;

      const formData = methods.getValues() as IMT5OrderFormData;
      const item = transformOrderFormToApi(formData, orderDetailData, isPendingApproval);

      const result = await compareOrder.mutateAsync({
        assignApprover: "",
        comment: "",
        serverId,
        items: [item],
      });

      if (!result.success || !result.data) {
        enqueueSnackbar(result?.error || "Failed to compare order changes. Please try again.", {
          variant: "error",
        });
        return;
      }

      const { needApproval, impliedLevel, logs } = result.data;
      const logsWithAudit = logs.map((log, i) => ({
        ...log,
        id: i,
        auditData: null,
        changedObject: null,
        targetType: null,
        riskLevel: null,
      }));
      approvalWorkflow.setCompareData({ needApproval, impliedLevel, logs: logsWithAudit });

      const fieldChanges: FieldChange[] = logs.map(log => {
        const keyParts = log.fieldKey.split("_");
        const tabName = keyParts[2] ?? "details";
        const fieldName = keyParts.slice(3).join("_");
        const formPath = `${tabName}.${fieldName}`;
        return {
          path: formPath,
          label: log.fieldKey.replace(/_/g, "."),
          oldValue: log.oldValue,
          newValue: log.newValue,
          riskLevel: getFieldRiskLevel(keyParts[0] as "mt5" | "mt4", keyParts[1], formPath),
          tabName,
        };
      });

      approvalWorkflow.openApprovalModalWithChanges(
        fieldChanges,
        impliedLevel as RiskLevel | null,
        item as unknown as Record<string, unknown>
      );
      setPendingAction(action);
    },
    [
      orderDetailData,
      serverId,
      methods,
      isPendingApproval,
      compareOrder,
      approvalWorkflow,
      getFieldRiskLevel,
    ]
  );

  const onSubmit = useCallback(() => compareAndOpenModal("save"), [compareAndOpenModal]);

  const handleApprovalSubmit = useCallback(
    async (approver: Approver | null, comment: string): Promise<boolean> => {
      try {
        if (!orderDetailData || !serverId) return false;

        const item = {
          ...(approvalWorkflow.formDataForSubmission as unknown as IMT5OrderUpdateItem),
          assignApprover: approver?.userEmail ?? "",
          approvalComment: comment || "",
        };

        await updateOrder({
          assignApprover: approver?.userEmail ?? "",
          comment: comment || "",
          serverId,
          items: [item],
        });

        await approvalWorkflow.submitApprovalRequest(approver, comment);

        invalidateEntityQueries();

        const needsApproval = approvalWorkflow.compareResults?.needApproval ?? false;
        if (needsApproval) {
          approvalWorkflow.closeApprovalModal();
          setWasApprovalSubmission(true);
          setSubmittedApprover(approver);
          setShowSuccessDialog(true);
        } else {
          closeModal();
        }

        return true;
      } catch (error) {
        console.error(`Failed to ${pendingAction} order:`, error);
        enqueueSnackbar(`Failed to ${pendingAction} order. Please try again.`, {
          variant: "error",
        });
        return false;
      }
    },
    [
      orderDetailData,
      serverId,
      approvalWorkflow,
      pendingAction,
      updateOrder,
      closeModal,
      invalidateEntityQueries,
    ]
  );

  // ─── Position Compare → Approval → Update flow ──────────────────
  const comparePositionAndOpenModal = useCallback(async () => {
    if (!positionDetailData || !serverId) return;

    const formData = methods.getValues() as IMT5PositionFormData;
    const item = transformPositionFormToApi(formData, positionDetailData, isPendingApproval);

    const result = await comparePosition.mutateAsync({
      assignApprover: "",
      comment: "",
      serverId,
      items: [item],
    });

    if (!result.success || !result.data) {
      enqueueSnackbar(result?.error || "Failed to compare position changes. Please try again.", {
        variant: "error",
      });
      return;
    }

    const { needApproval, impliedLevel, logs } = result.data;
    const logsWithAudit = logs.map((log, i) => ({
      ...log,
      id: i,
      auditData: null,
      changedObject: null,
      targetType: null,
      riskLevel: null,
    }));
    approvalWorkflow.setCompareData({ needApproval, impliedLevel, logs: logsWithAudit });

    const fieldChanges: FieldChange[] = logs.map(log => {
      const keyParts = log.fieldKey.split("_");
      const tabName = keyParts[2] ?? "details";
      const fieldName = keyParts.slice(3).join("_");
      const formPath = `${tabName}.${fieldName}`;
      return {
        path: formPath,
        label: log.fieldKey.replace(/_/g, "."),
        oldValue: log.oldValue,
        newValue: log.newValue,
        riskLevel: getFieldRiskLevel(keyParts[0] as "mt5" | "mt4", keyParts[1], formPath),
        tabName,
      };
    });

    approvalWorkflow.openApprovalModalWithChanges(
      fieldChanges,
      impliedLevel as RiskLevel | null,
      item as unknown as Record<string, unknown>
    );
    setPendingAction("save");
  }, [
    positionDetailData,
    serverId,
    methods,
    isPendingApproval,
    comparePosition,
    approvalWorkflow,
    getFieldRiskLevel,
  ]);

  const onSubmitPosition = useCallback(
    () => comparePositionAndOpenModal(),
    [comparePositionAndOpenModal]
  );

  const handlePositionApprovalSubmit = useCallback(
    async (approver: Approver | null, comment: string): Promise<boolean> => {
      try {
        if (!positionDetailData || !serverId) return false;

        const item = {
          ...(approvalWorkflow.formDataForSubmission as unknown as IMT5PositionUpdateItem),
          assignApprover: approver?.userEmail ?? "",
          approvalComment: comment || "",
        };

        await updatePosition({
          assignApprover: approver?.userEmail ?? "",
          comment: comment || "",
          serverId,
          items: [item],
        });

        await approvalWorkflow.submitApprovalRequest(approver, comment);

        invalidateEntityQueries();

        const needsApproval = approvalWorkflow.compareResults?.needApproval ?? false;
        if (needsApproval) {
          approvalWorkflow.closeApprovalModal();
          setWasApprovalSubmission(true);
          setSubmittedApprover(approver);
          setShowSuccessDialog(true);
        } else {
          closeModal();
        }

        return true;
      } catch {
        return false;
      }
    },
    [
      positionDetailData,
      serverId,
      approvalWorkflow,
      updatePosition,
      closeModal,
      invalidateEntityQueries,
    ]
  );

  // ─── Deal Compare → Approval → Update flow ──────────────────────
  const compareDealAndOpenModal = useCallback(async () => {
    if (!dealDetailData || !serverId) return;

    const formData = methods.getValues() as IMT5DealFormData;
    const item = transformDealFormToApi(formData, dealDetailData, isPendingApproval);

    const result = await compareDeal.mutateAsync({
      assignApprover: "",
      comment: "",
      serverId,
      items: [item],
    });

    if (!result.success || !result.data) {
      enqueueSnackbar(result?.error || "Failed to compare deal changes. Please try again.", {
        variant: "error",
      });
      return;
    }

    const { needApproval, impliedLevel, logs } = result.data;
    const logsWithAudit = logs.map((log, i) => ({
      ...log,
      id: i,
      auditData: null,
      changedObject: null,
      targetType: null,
      riskLevel: null,
    }));
    approvalWorkflow.setCompareData({ needApproval, impliedLevel, logs: logsWithAudit });

    const fieldChanges: FieldChange[] = logs.map(log => {
      const keyParts = log.fieldKey.split("_");
      const tabName = keyParts[2] ?? "details";
      const fieldName = keyParts.slice(3).join("_");
      const formPath = `${tabName}.${fieldName}`;
      return {
        path: formPath,
        label: log.fieldKey.replace(/_/g, "."),
        oldValue: log.oldValue,
        newValue: log.newValue,
        riskLevel: getFieldRiskLevel(keyParts[0] as "mt5" | "mt4", keyParts[1], formPath),
        tabName,
      };
    });

    approvalWorkflow.openApprovalModalWithChanges(
      fieldChanges,
      impliedLevel as RiskLevel | null,
      item as unknown as Record<string, unknown>
    );
    setPendingAction("save");
  }, [
    dealDetailData,
    serverId,
    methods,
    isPendingApproval,
    compareDeal,
    approvalWorkflow,
    getFieldRiskLevel,
  ]);

  const onSubmitDeal = useCallback(() => compareDealAndOpenModal(), [compareDealAndOpenModal]);

  const handleDealApprovalSubmit = useCallback(
    async (approver: Approver | null, comment: string): Promise<boolean> => {
      try {
        if (!dealDetailData || !serverId) return false;

        const item = {
          ...(approvalWorkflow.formDataForSubmission as unknown as IMT5DealUpdateItem),
          assignApprover: approver?.userEmail ?? "",
          approvalComment: comment || "",
        };

        await updateDeal({
          assignApprover: approver?.userEmail ?? "",
          comment: comment || "",
          serverId,
          items: [item],
        });

        await approvalWorkflow.submitApprovalRequest(approver, comment);

        invalidateEntityQueries();

        const needsApproval = approvalWorkflow.compareResults?.needApproval ?? false;
        if (needsApproval) {
          approvalWorkflow.closeApprovalModal();
          setWasApprovalSubmission(true);
          setSubmittedApprover(approver);
          setShowSuccessDialog(true);
        } else {
          closeModal();
        }

        return true;
      } catch {
        enqueueSnackbar("Failed to update deal. Please try again.", { variant: "error" });
        return false;
      }
    },
    [dealDetailData, serverId, approvalWorkflow, updateDeal, closeModal, invalidateEntityQueries]
  );

  // ─── Form reset on entity change ──────────────────────────────────
  // Track which entity+data has been used to initialize the form, preventing
  // repeated resets when detail data references change (e.g., positionDetailData
  // refetch triggered by treeLogin changes), while still allowing the first
  // data-loaded reset.
  const formInitRef = useRef<string | null>(null);
  useEffect(() => {
    if (!isOpen || !entityType || !entityId) {
      formInitRef.current = null;
      return;
    }

    // Use detail API data when available
    if (entityType === "position" && positionDetailData) {
      const key = `position:${entityId}:loaded`;
      if (formInitRef.current !== key) {
        formInitRef.current = key;
        reset(transformPositionDetailApiToForm(positionDetailData));
      }
      return;
    }
    if (entityType === "order" && orderDetailData) {
      const key = `order:${entityId}:loaded`;
      if (formInitRef.current !== key) {
        formInitRef.current = key;
        reset(transformOrderDetailApiToForm(orderDetailData));
      }
      return;
    }
    if (entityType === "deal" && dealDetailData) {
      const key = `deal:${entityId}:loaded`;
      if (formInitRef.current !== key) {
        formInitRef.current = key;
        reset(transformDealApiToForm(dealDetailData));
      }
      return;
    }

    // Data not yet loaded — reset to defaults only once per entity switch
    const pendingKey = `${entityType}:${entityId}:pending`;
    if (formInitRef.current !== pendingKey && !formInitRef.current?.endsWith(":loaded")) {
      formInitRef.current = pendingKey;
      reset(getSchemaAndDefaults(entityType).defaults);
    }
  }, [isOpen, entityType, entityId, reset, orderDetailData, dealDetailData, positionDetailData]);

  // ─── Clean up approval state when modal closes ───────────────────
  useEffect(() => {
    const prevIsOpen = prevIsOpenRef.current;
    prevIsOpenRef.current = isOpen;

    if (prevIsOpen && !isOpen) {
      approvalWorkflow.resetWorkflow();
      setPendingAction(null);
      setShowSuccessDialog(false);
      setWasApprovalSubmission(false);
      setSubmittedApprover(null);
      if (isUnlocked) {
        toggleUnlock();
      }
    }
  }, [isOpen, approvalWorkflow, isUnlocked, toggleUnlock]);

  // ─── Render ───────────────────────────────────────────────────────
  if (!isOpen || !entityType || !entityId) return null;

  return (
    <>
      <ApprovalSuccessDialog
        open={showSuccessDialog}
        onClose={() => {
          setShowSuccessDialog(false);
          closeModal();
        }}
        needApproval={wasApprovalSubmission}
        approver={submittedApprover}
      />
      <Dialog
        open={isOpen && !showSuccessDialog}
        onClose={closeModal}
        aria-labelledby="MT5-Order-Configuration"
        fullWidth
        maxWidth="lg"
        scroll="paper"
