                </Stack>
              </Stack>
            </DialogTitle>
            <Divider />

            {/* ─── Account Info ─── */}
            <Box sx={{ px: 1, pt: 1 }}>
              <Stack direction="row" alignItems="center" gap={1}>
                {!treeLogin || isLoadingAccountInfo ? (
