                  )}
                  <DialogContent
                    sx={{
                      height: "70vh",
                      maxHeight: 600,
                      overflow: "auto",
                      px: selectedTab === "visualization" ? 0 : 1.5,
                      py: selectedTab === "visualization" ? 0 : 1,
                      pointerEvents: isSubmitting || isUpdatingAny ? "none" : "auto",
                      opacity: isSubmitting || isUpdatingAny ? 0.6 : 1,
                      ...((selectedTab === "visualization" || selectedTab === "ticks") && {
                        display: "flex",
                        flexDirection: "column",
