                  >
                    {selectedTab === "details" && (
                      <Details
                        entityType={entityType}
                        isLoading={isDetailLoading}
                        enumData={enumData}
                        positionEnumData={positionEnumData}
                        dealEnumData={dealEnumData}
                        orderDetailData={orderDetailData}
                        dealDetailData={dealDetailData}
                        positionDetailData={positionDetailData}
                        switchEntity={switchEntity}
                        symbols={symbols}
                        isLoadingSymbols={isLoadingSymbols}
                        hasOrderFieldPermission={hasPermissionOrder}
                        hasPositionFieldPermission={hasPermissionPosition}
                        hasDealFieldPermission={hasPermissionDeal}
                      />
                    )}
                    {/* Visualization & Ticks: keep mounted, toggle visibility to preserve chart/grid state */}
                    <Box
                      sx={{
                        display: selectedTab === "visualization" ? "flex" : "none",
                        flexDirection: "column",
                        flex: 1,
                        minHeight: 0,
                      }}
                    >
                      <Visualization
                        treeData={effectiveTreeData}
                        entityType={entityType}
                        entityId={entityId}
