                    </Box>
                    <Box
                      sx={{
                        display: selectedTab === "ticks" ? "flex" : "none",
                        flexDirection: "column",
                        flex: 1,
                        minHeight: 0,
                      }}
                    >
                      <Ticks treeData={effectiveTreeData} entityType={entityType} entityId={entityId} />
                    </Box>
                    {selectedTab === "journal" && <Journal />}
                  </DialogContent>
                </MT5TicksDataProvider>
              </FormProvider>
            </ApprovalModeContext.Provider>

            {/* ─── Action Bar ─── */}
            <Divider />
            <DialogActions
              sx={{
                justifyContent: "space-between",
                px: 3,
                pb: 1,
              }}
            >
              <Box sx={{ display: "flex", gap: 1 }}>
                <Button
                  onClick={handleRefreshData}
                  disabled={
                    isSubmitting || isUpdatingAny || isRefreshing || orchestrator.isFetching
