                  startIcon={isRefreshing ? <CircularProgress size={16} /> : <MdRefresh />}
                  color="warning"
                >
                  {isRefreshing ? "Refreshing..." : "Refresh Data"}
                </Button>
                <Tooltip title={!canReport ? "Insufficient permissions" : ""}>
                  <span>
                    <Button
                      onClick={() => setReportModalOpen(true)}
                      disabled={!treeData || !canReport}
                      startIcon={<HiOutlineDocumentReport />}
                    >
                      Report
                    </Button>
                  </span>
                </Tooltip>
              </Box>
              <Box sx={{ display: "flex", gap: 1 }}>
                <Button onClick={closeModal} disabled={isSubmitting || isUpdatingAny}>
                  Cancel
                </Button>
                {entityType === "order" && toHistoryBaseEligibility.eligible && (
                  <Tooltip title={toHistoryFullEligibility.tooltip}>
                    <span>
                      <Button
                        variant="outlined"
                        color="inherit"
                        disabled={
                          !toHistoryFullEligibility.eligible || isSubmitting || isUpdatingAny
                        }
                        onClick={() => {
                          if (formState.isDirty) {
                            setDirtyConfirmAction("toHistory");
                          } else {
                            setToHistoryDialogOpen(true);
                          }
                        }}
                      >
                        To History
                      </Button>
                    </span>
                  </Tooltip>
                )}
                {showReopenButton && (
                  <Tooltip
                    title={
                      !canReopen
                        ? "Insufficient permissions"
                        : !isPendingOrderType(currentOrder!.type)
                          ? "Only pending orders can be reopened"
                          : "Reopen this closed pending order"
                    }
                  >
                    <span>
                      <Button
                        variant="contained"
                        color="warning"
                        disabled={
                          !canReopen ||
                          !isPendingOrderType(currentOrder!.type) ||
                          isSubmitting ||
                          isUpdatingAny ||
                          isPendingApproval
                        }
                        startIcon={<LuRefreshCw />}
                        onClick={() => {
                          if (formState.isDirty) {
                            setDirtyConfirmAction("reopen");
                          } else {
                            setReopenDialogOpen(true);
                          }
                        }}
                      >
                        Reopen
                      </Button>
                    </span>
                  </Tooltip>
                )}
                <Button
                  variant="contained"
                  disabled={isSubmitting || isUpdatingAny || !isDirty || isPendingApproval}
                  startIcon={
                    isSubmitting || isUpdatingAny ? (
                      <CircularProgress size={16} />
                    ) : isPendingApproval ? (
                      <MdLock />
                    ) : isUnlocked ? (
                      <MdSend />
                    ) : (
                      <MdSave />
                    )
                  }
                  aria-label={
                    isPendingApproval
                      ? `Cannot save changes - ${entityType} is pending approval`
                      : undefined
                  }
                  onClick={handleSubmit(
                    entityType === "deal"
                      ? onSubmitDeal
                      : entityType === "position"
                        ? onSubmitPosition
                        : onSubmit
                  )}
                >
                  {isPendingApproval
                    ? "Pending Approval"
                    : isSubmitting
                      ? "Checking..."
                      : isUpdatingAny
                        ? "Saving..."
                        : isUnlocked
                          ? "Save with Approval"
                          : "Save Changes"}
                </Button>
              </Box>
            </DialogActions>
          </>
        )}
      </Dialog>

      {/* Approval Request Modal */}
      <ApprovalRequestModal
        open={approvalWorkflow.isApprovalModalOpen}
        onClose={approvalWorkflow.closeApprovalModal}
        onSubmit={
          entityType === "deal"
            ? handleDealApprovalSubmit
            : entityType === "position"
              ? handlePositionApprovalSubmit
              : handleApprovalSubmit
        }
        changes={approvalWorkflow.changedFields}
        highestRiskLevel={approvalWorkflow.highestRiskLevel}
        isSubmitting={approvalWorkflow.isSubmitting || isUpdatingAny}
        isSuccess={approvalWorkflow.isSuccess}
        selectedApprover={approvalWorkflow.selectedApprover}
        needApproval={approvalWorkflow.compareResults?.needApproval ?? false}
        serverId={serverId ?? 0}
        module={entityType === "deal" ? "Deal" : entityType === "position" ? "Position" : "Order"}
        doubleConfirmationCheck
      />

      {/* Unsaved changes confirmation */}
      <ConfirmationDialog
        open={dirtyConfirmAction !== null}
        onClose={() => setDirtyConfirmAction(null)}
        title="Unsaved Changes"
        description="You have unsaved changes that will be lost. Do you want to continue?"
        confirmButtonLabel="Continue"
        onConfirm={() => {
          const action = dirtyConfirmAction;
          setDirtyConfirmAction(null);
          if (action === "toHistory") setToHistoryDialogOpen(true);
          if (action === "reopen") setReopenDialogOpen(true);
        }}
      />

      {/* Reopen Confirmation Dialog */}
      {currentOrderForDialog && (
        <MT5OrderReopenDialog
          open={reopenDialogOpen}
          onClose={() => setReopenDialogOpen(false)}
          orders={[currentOrderForDialog]}
          serverName={currentServerName}
          onSuccess={() => {
            setReopenDialogOpen(false);
            handleRefreshData();
            invalidateEntityQueries();
          }}
        />
      )}

      {/* To History Dialog */}
      {currentOrderForDialog && (
        <MT5OrderToHistoryDialog
          open={toHistoryDialogOpen}
          onClose={() => setToHistoryDialogOpen(false)}
          orders={[currentOrderForDialog]}
          serverId={serverId ?? 0}
          serverName={currentServerName}
          onSuccess={() => {
            setToHistoryDialogOpen(false);
            handleRefreshData();
            invalidateEntityQueries();
          }}
        />
      )}

      {/* Report Modal */}
      <MT5ReportModal
        open={reportModalOpen}
        onClose={() => setReportModalOpen(false)}
        serverName={currentServerName}
        serverId={serverId ?? 0}
        login={treeLogin}
        ticket={entityId ?? 0}
        ticketType={entityType ?? "order"}
        treeData={effectiveTreeData}
      />
    </>
  );
}

