/** Check if an ISO time string is valid (not empty, not 1970-01-01) */
function isValidTime(val: string | undefined | null): boolean {
  if (!val) return false;
  const ms = new Date(val).getTime();
  if (isNaN(ms) || ms <= 0) return false;
  const d = new Date(ms);
  return d.getUTCFullYear() > 1970;
}

/** Convert ISO time string to seconds for chart */
function isoToChartSec(val: string): number {
  return Math.floor(new Date(val).getTime() / 1000);
}

/** Convert ticks to line data (dedup per second, keep last value) */
function toLineData(
  ticks: IMT5TicksHistoryItem[],
  getValue: (t: IMT5TicksHistoryItem) => number | string
) {
  const secMap = new Map<number, number>();
  ticks
    .filter(t => Number(getValue(t)) > 0)
    .forEach(t =>
      secMap.set(Math.floor(new Date(t.datetime).getTime() / 1000), Number(getValue(t)))
    );
  return Array.from(secMap.entries())
    .sort((a, b) => a[0] - b[0])
    .map(([time, value]) => ({ time: time as UTCTimestamp, value }));
}

/**
 * Inject synthetic data points at event times that don't exist in the series data.
 * Uses forward-fill (previous value) so the line shape stays correct.
 * This ensures timeToCoordinate works for event times that fall in tick gaps.
 */
function injectEventTimes(
  data: { time: UTCTimestamp; value: number }[],
  eventTimes: number[]
): { time: UTCTimestamp; value: number }[] {
  if (data.length === 0 || eventTimes.length === 0) return data;

  const existing = new Set(data.map(d => d.time as number));
  const toInject = Array.from(new Set(eventTimes)).filter(
    t =>
      !existing.has(t) &&
      t >= (data[0].time as number) &&
      t <= (data[data.length - 1].time as number)
  );
  if (toInject.length === 0) return data;

  const result = [...data];
  for (const t of toInject) {
    // Find the previous data point for forward-fill
    let prevVal = data[0].value;
    for (let i = data.length - 1; i >= 0; i--) {
      if ((data[i].time as number) <= t) {
        prevVal = data[i].value;
        break;
      }
    }
    result.push({ time: t as UTCTimestamp, value: prevVal });
  }
  return result.sort((a, b) => (a.time as number) - (b.time as number));
}

/** Find the position relevant to the currently selected entity */
function findActivePosition(
  treeData: IMT5TicketTreeFlatResponse,
  entityType: MT5EntityType,
  entityId: number
) {
  if (entityType === "position") {
    return treeData.positions.find(p => p.positionTicket === entityId);
  }
  if (entityType === "order") {
    const order = treeData.orders.find(o => o.order === entityId);
    if (order) return treeData.positions.find(p => p.positionTicket === order.positionID);
  }
  if (entityType === "deal") {
    const deal = treeData.deals.find(d => d.deal === entityId);
    if (deal) {
      const order = treeData.orders.find(o => o.order === deal.order);
      if (order) return treeData.positions.find(p => p.positionTicket === order.positionID);
    }
  }
  return treeData.positions[0];
}

export default function Visualization({ treeData, entityType, entityId }: VisualizationProps) {
