  const [containerReady, setContainerReady] = useState(0);
  const chartRef = useRef<ReturnType<typeof createChart> | null>(null);
  const bidSeriesRef = useRef<ISeriesApi<"Line"> | null>(null);
  const askSeriesRef = useRef<ISeriesApi<"Line"> | null>(null);
  const lastSeriesRef = useRef<ISeriesApi<"Line"> | null>(null);
  const priceLinesRef = useRef<IPriceLine[]>([]);

  // Context menu
  const [menuPos, setMenuPos] = useState<{ x: number; y: number } | null>(null);
  const [options, setOptions] = useState({
    crosshair: true,
    bidLine: true,
    askLine: true,
    lastLine: true,
    grid: true,
    priceLevels: true,
    timeMarks: true,
    autoVerticalScale: true,
  });
  const optionsRef = useRef(options);
  optionsRef.current = options;

  const handleContextMenu = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setMenuPos({ x: e.clientX, y: e.clientY });
  }, []);

  const handleCloseMenu = useCallback(() => setMenuPos(null), []);

  const toggleOption = useCallback((key: keyof typeof options) => {
    setOptions(prev => {
      const next = { ...prev, [key]: !prev[key] };
      const chart = chartRef.current;
      if (!chart) return next;

      switch (key) {
        case "crosshair":
          chart.applyOptions({
            crosshair: next.crosshair
              ? {
                  mode: CrosshairMode.Normal,
                  vertLine: { visible: true, labelVisible: true },
                  horzLine: { visible: true, labelVisible: true },
                }
              : {
                  vertLine: { visible: false, labelVisible: false },
                  horzLine: { visible: false, labelVisible: false },
                },
          });
          if (!next.crosshair && tooltipRef.current) {
            tooltipRef.current.style.display = "none";
          }
          break;
        case "bidLine":
          bidSeriesRef.current?.applyOptions({ visible: next.bidLine });
          break;
        case "askLine":
          askSeriesRef.current?.applyOptions({ visible: next.askLine });
          break;
        case "lastLine":
          lastSeriesRef.current?.applyOptions({ visible: next.lastLine });
          break;
        case "grid":
          chart.applyOptions({
            grid: {
              vertLines: { visible: next.grid },
              horzLines: { visible: next.grid },
            },
          });
          break;
        case "priceLevels":
          priceLinesRef.current.forEach(pl => {
            pl.applyOptions({
              lineVisible: next.priceLevels,
              axisLabelVisible: next.priceLevels,
              title: next.priceLevels ? pl.options().title : "",
            });
          });
          break;
        case "timeMarks": {
          const lineContainer = containerRef.current?.querySelector(
            ".marker-lines"
          ) as HTMLElement | null;
          if (lineContainer) lineContainer.style.display = next.timeMarks ? "" : "none";
          break;
        }
        case "autoVerticalScale":
          chart.applyOptions({
            rightPriceScale: { autoScale: next.autoVerticalScale },
            handleScale: {
              axisPressedMouseMove: { time: true, price: next.autoVerticalScale },
              mouseWheel: true,
              pinch: true,
            },
          });
          break;
      }
      return next;
    });
    setMenuPos(null);
  }, []);

  // Keyboard shortcuts
  useEffect(() => {
    const shortcutMap: Record<string, keyof typeof options> = {
      c: "crosshair",
      b: "bidLine",
      a: "askLine",
      l: "lastLine",
      g: "grid",
    };
    const handleKeyDown = (e: KeyboardEvent) => {
      const key = shortcutMap[e.key.toLowerCase()];
      if (key && !e.ctrlKey && !e.metaKey && !e.altKey) {
        toggleOption(key);
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [toggleOption]);

  useEffect(() => {
    if (!containerRef.current || !serverId || !treeData || isLoading || ticks.length === 0) return;

    const container = containerRef.current;
    const tooltipEl = tooltipRef.current;

    // Wait for flex layout to resolve so container has height
    if (container.clientHeight < 50) {
      const waitRo = new ResizeObserver(() => {
        if (container.clientHeight >= 50) {
          waitRo.disconnect();
          setContainerReady(v => v + 1);
        }
      });
      waitRo.observe(container);
      return () => waitRo.disconnect();
    }

    const bgColor = theme.palette.background.paper;
    const textColor = isDark ? "#d4d4d4" : "#444444";
    const gridColor = isDark ? "#333333" : "#d8d8d8";
    const borderColor = isDark ? "#444444" : "#cccccc";
    const crosshairColor = isDark ? "#aaaaaa" : "#333333";

    const chart = createChart(container, {
      autoSize: true,
      layout: {
        background: { color: bgColor },
        textColor,
        attributionLogo: false,
      },
      grid: {
        vertLines: { color: gridColor, style: LineStyle.Dashed },
        horzLines: { color: gridColor, style: LineStyle.Dashed },
      },
      crosshair: {
        mode: CrosshairMode.Normal,
        vertLine: {
          color: crosshairColor,
          width: 1,
          style: LineStyle.Solid,
          labelBackgroundColor: crosshairColor,
        },
        horzLine: {
          color: crosshairColor,
          width: 1,
          style: LineStyle.Solid,
          labelBackgroundColor: crosshairColor,
        },
      },
      handleScroll: {
        mouseWheel: false,
        pressedMouseMove: true,
        horzTouchDrag: true,
        vertTouchDrag: true,
      },
      handleScale: {
        axisPressedMouseMove: { time: true, price: true },
        mouseWheel: true,
        pinch: true,
      },
      rightPriceScale: {
        visible: true,
        borderColor,
        autoScale: true,
        scaleMargins: { top: 0.08, bottom: 0.08 },
        minimumWidth: 80,
      },
      localization: {
        timeFormatter: (time: number) => formatDateTimeUTCWithSeconds(new Date(time * 1000)),
      },
      timeScale: {
        borderColor,
        timeVisible: true,
        secondsVisible: false,
        fixLeftEdge: false,
        fixRightEdge: false,
        barSpacing: 12,
        minBarSpacing: 1,
        tickMarkFormatter: (time: number) => {
          const d = new Date(time * 1000);
          const hh = String(d.getUTCHours()).padStart(2, "0");
          const mi = String(d.getUTCMinutes()).padStart(2, "0");
          return `${hh}:${mi}`;
        },
      },
    });

    chartRef.current = chart;

    // Detect precision from bid values (e.g. 4643.92 → 2, 1.14735 → 5)
    let maxDecimals = 0;
    for (const t of ticks) {
      const s = String(t.bid);
      const dot = s.indexOf(".");
      if (dot !== -1) {
        const d = s.length - dot - 1;
        if (d > maxDecimals) maxDecimals = d;
      }
      if (maxDecimals >= 5) break; // no need to check more
    }
    const precision = maxDecimals || 2;
    const minMove = 1 / Math.pow(10, precision);

    const seriesCommon = {
      lineWidth: 1 as const,
      lastValueVisible: false,
      priceLineVisible: false,
      priceScaleId: "right",
      priceFormat: { type: "price" as const, precision, minMove },
      crosshairMarkerVisible: false,
      pointMarkersVisible: false,
    };

    const bidSeries = chart.addSeries(LineSeries, { ...seriesCommon, color: "#1565c0" });
    bidSeriesRef.current = bidSeries;

    const askSeries = chart.addSeries(LineSeries, { ...seriesCommon, color: "#c62828" });
    askSeriesRef.current = askSeries;

    const lastSeries = chart.addSeries(LineSeries, {
      ...seriesCommon,
      color: "#FF6D00",
    });
    lastSeriesRef.current = lastSeries;

    // Hide time labels permanently on first drag
    let timeLabelsHidden = false;

    const onMouseDown = (e: MouseEvent) => {
      // Only track left click
      if (e.button !== 0) return;
      timeLabelsHidden = true;

      if (optionsRef.current.autoVerticalScale) {
        chart.applyOptions({ rightPriceScale: { autoScale: false } });
      }
    };

    container.addEventListener("mousedown", onMouseDown);

    const tickByTime = new Map<number, IMT5TicksHistoryItem>();
    ticks.forEach(t => tickByTime.set(Math.floor(new Date(t.datetime).getTime() / 1000), t));

    // Collect all event times from tree data so we can inject synthetic
    // data points into the series (fills gaps where no tick exists at that second).
    const allEventTimes: number[] = [];
    for (const pos of treeData.positions) {
      if (isValidTime(pos.timeCreate)) allEventTimes.push(isoToChartSec(pos.timeCreate));
    }
    const allOrders = treeData.orders;
    const allDeals = treeData.deals;
    for (const order of allOrders) {
      const t = isValidTime(order.timeSetupMsc) ? order.timeSetupMsc : order.timeSetup;
      if (isValidTime(t)) allEventTimes.push(isoToChartSec(t));
      const td = isValidTime(order.timeDoneMsc) ? order.timeDoneMsc : order.timeDone;
      if (isValidTime(td)) allEventTimes.push(isoToChartSec(td));
    }
    for (const deal of allDeals) {
      const t = isValidTime(deal.timeMsc) ? deal.timeMsc : deal.time;
      if (isValidTime(t)) allEventTimes.push(isoToChartSec(t));
    }

    // Generate logical times from tick data.
    // If we have gaps, lightweight-charts naturally connects the dots.
    const bidData = injectEventTimes(
      toLineData(ticks, t => t.bid),
      allEventTimes
    );
    const askData = injectEventTimes(
      toLineData(ticks, t => t.ask),
      allEventTimes
    );
    const lastData = injectEventTimes(
      toLineData(ticks, t => t.last),
      allEventTimes
    );

    // Get the min and max timestamp from the tick data
    const bidFirst = bidData.length > 0 ? (bidData[0].time as number) : 0;
    const bidLast = bidData.length > 0 ? (bidData[bidData.length - 1].time as number) : 0;

    if (bidData.length > 0) bidSeries.setData(bidData);
    if (askData.length > 0) askSeries.setData(askData);
    if (lastData.length > 0) lastSeries.setData(lastData);

    // Open Price & Current Price & SL horizontal lines
    const activePos = findActivePosition(treeData, entityType, entityId);
    const openPrice = Number(activePos?.priceOpen ?? 0);
    const currentPrice = Number(activePos?.priceCurrent ?? 0);
    const priceSL = Number(activePos?.priceSL ?? 0);
    priceLinesRef.current = [];

    // Price lines — all excluded from autoScale so they don't flatten the chart
    const plCommon = {
      lineWidth: 1 as const,
      axisLabelVisible: true,
      autoscaleInfoProvider: () => null,
    };

    // In MT5:
    // Open Price is usually a solid Green line (or Dashed Green)
    // TP (Take Profit) is usually a solid or dashed Green/Blue line
    // SL (Stop Loss) is usually a solid or dashed Red line
    // Current Price is usually just the active Bid/Ask line, but a dashed line is helpful for historical reference
    if (openPrice) {
      priceLinesRef.current.push(
        bidSeries.createPriceLine({
          ...plCommon,
          lineStyle: LineStyle.Dashed,
          price: openPrice,
          color: "#4caf50",
          title: "Open Price",
        })
      );
    }
    if (priceSL) {
      priceLinesRef.current.push(
        bidSeries.createPriceLine({
          ...plCommon,
          lineStyle: LineStyle.Dashed,
          price: priceSL,
          color: "#ef5350",
          title: "SL",
        })
      );
    }
    const priceTP = Number(activePos?.priceTP ?? 0);
    if (priceTP) {
      priceLinesRef.current.push(
        bidSeries.createPriceLine({
          ...plCommon,
          lineStyle: LineStyle.Dashed,
          price: priceTP,
          color: "#2196f3",
          title: "TP",
        })
      );
    }
    // We only draw current price if the position is still open (priceCurrent is valid and position is not closed)
    // Or if we specifically want to mark the final close price.
    // If we do draw it, make it distinct (e.g. dotted gray)
    let secondaryPrice = 0;

    if (entityType === "deal") {
      const activeDeal = treeData.deals.find(d => d.deal === entityId);
      secondaryPrice = Number(activeDeal?.price ?? 0);
    } else if (entityType === "order") {
      const activeOrder = treeData.orders.find(o => o.order === entityId);
      secondaryPrice = Number(activeOrder?.priceOrder ?? 0);
      if (!secondaryPrice || isNaN(secondaryPrice)) {
        secondaryPrice = Number(activeOrder?.priceCurrent ?? 0);
      }
    } else {
      secondaryPrice = currentPrice;
    }

    if (secondaryPrice && secondaryPrice !== openPrice) {
      priceLinesRef.current.push(
        bidSeries.createPriceLine({
          ...plCommon,
          lineStyle: LineStyle.Dotted,
          price: secondaryPrice,
          color: isDark ? "#9e9e9e" : "#616161",
          title: "Current Price",
        })
      );
    }

    // Collect event labels with buy/sell direction and price
    // We only collect events that actually happened within our available tick data window.
    // If an event is completely outside our tick data, we can't accurately draw it on the X-axis anyway.
    interface EventLabel {
      timeSec: number;
      text: string;
      isBuy: boolean;
      price: number;
      eType: MT5EntityType;
      eId: number;
      entryType?: string;
      lineOnly?: boolean;
    }
    const events: EventLabel[] = [];

    const isBuyAction = (val: string) => /buy/i.test(val);

    const pushEvent = (evt: EventLabel) => {
      // Only include events within the tick data window
      if (evt.timeSec >= bidFirst && evt.timeSec <= bidLast) {
        events.push(evt);
      }
    };

    // Positions
    for (const pos of treeData.positions) {
      if (isValidTime(pos.timeCreate)) {
        pushEvent({
          timeSec: isoToChartSec(pos.timeCreate),
          text: `Position #${pos.positionTicket} created`,
          isBuy: isBuyAction(pos.action),
          price: Number(pos.priceOpen),
          eType: "position",
          eId: pos.positionTicket,
        });
      }
    }

    // Orders
    for (const order of allOrders) {
      const orderIsBuy = isBuyAction(order.type);
      const isMarket = isNaN(Number(order.priceOrder)) || Number(order.priceOrder) === 0;
      let orderPrice = isMarket ? Number(order.priceCurrent) : Number(order.priceOrder);

      // Fallback for Market orders if priceCurrent is empty
      if (!orderPrice) {
        const linkedDeal = allDeals.find(d => d.order === order.order);
        if (linkedDeal && Number(linkedDeal.price)) {
          orderPrice = Number(linkedDeal.price);
        } else {
          const linkedPos = treeData.positions.find(p => p.positionTicket === order.positionID);
          if (linkedPos && Number(linkedPos.priceOpen)) {
            orderPrice = Number(linkedPos.priceOpen);
          }
        }
      }

      // Order placed (timeSetup)
      const setupTime = isValidTime(order.timeSetupMsc) ? order.timeSetupMsc : order.timeSetup;
      if (isValidTime(setupTime)) {
        pushEvent({
          timeSec: isoToChartSec(setupTime),
          text: `Order #${order.order} placed`,
          isBuy: orderIsBuy,
          price: orderPrice,
          eType: "order",
          eId: order.order,
        });
      }
      // Order timeDone — only if state ≠ FILLED (Deal marker already covers it) and timeDone valid
      const orderState = order.state?.toUpperCase() ?? "";
      const doneTime = isValidTime(order.timeDoneMsc) ? order.timeDoneMsc : order.timeDone;
      if (isValidTime(doneTime) && orderState !== "FILLED") {
        const doneSec = isoToChartSec(doneTime);
        const setupSec = isValidTime(setupTime) ? isoToChartSec(setupTime) : 0;
        if (doneSec !== setupSec) {
          const stateSuffix =
            orderState === "CANCELED"
              ? "canceled"
              : orderState === "EXPIRED"
                ? "expired"
                : orderState === "REJECTED"
                  ? "rejected"
                  : "closed";
          pushEvent({
            timeSec: doneSec,
            text: `Order #${order.order} ${stateSuffix}`,
            isBuy: orderIsBuy,
            price: orderPrice,
            eType: "order",
            eId: order.order,
            lineOnly: true,
          });
        }
      }
    }

    // Deals
    for (const deal of allDeals) {
      const dealTime = isValidTime(deal.timeMsc) ? deal.timeMsc : deal.time;
      if (isValidTime(dealTime)) {
        pushEvent({
          timeSec: isoToChartSec(dealTime),
          text: `Deal #${deal.deal} created`,
          isBuy: isBuyAction(deal.action),
          price: Number(deal.price),
          eType: "deal",
          eId: deal.deal,
          entryType: deal.entry,
        });
      }
    }

    // Connect IN and OUT deals with a dashed line
    const dealsByPos = new Map<number, (typeof treeData.deals)[0][]>();
    allDeals.forEach(d => {
      if (!dealsByPos.has(d.positionID)) dealsByPos.set(d.positionID, []);
      dealsByPos.get(d.positionID)!.push(d);
    });

    dealsByPos.forEach(posDeals => {
      const inDeals = posDeals.filter(d => {
        const entry = d.entry?.toUpperCase();
        return entry === "IN" || entry === "IN/OUT";
      });
      const outDeals = posDeals.filter(d => d.entry?.toUpperCase().startsWith("OUT"));

      inDeals.forEach(inD => {
        outDeals.forEach(outD => {
          const inTime = isoToChartSec(isValidTime(inD.timeMsc) ? inD.timeMsc : inD.time);
          const outTime = isoToChartSec(isValidTime(outD.timeMsc) ? outD.timeMsc : outD.time);
          const inPrice = Number(inD.price);
          const outPrice = Number(outD.price);

          if (
            inTime &&
            outTime &&
            inTime < outTime &&
            inTime >= bidFirst - 10 &&
            inTime <= bidLast + 10 &&
            outTime >= bidFirst - 10 &&
            outTime <= bidLast + 10
          ) {
            const isBuy = isBuyAction(inD.action);
            const lineColor = isBuy ? "#2196f3" : "#ef5350";

            const trendSeries = chart.addSeries(LineSeries, {
              lineWidth: 1,
              lineStyle: LineStyle.Dashed,
              color: lineColor,
              lastValueVisible: false,
              priceLineVisible: false,
              crosshairMarkerVisible: false,
              pointMarkersVisible: false,
              autoscaleInfoProvider: () => null,
            });

            trendSeries.setData([
              { time: inTime as UTCTimestamp, value: inPrice },
              { time: outTime as UTCTimestamp, value: outPrice },
            ]);
          }
        });
      });
    });

    // Group by same second
    const grouped = new Map<number, EventLabel[]>();
    for (const ev of events) {
      const arr = grouped.get(ev.timeSec) || [];
      arr.push(ev);
      grouped.set(ev.timeSec, arr);
    }

    // Sort by price (descending — higher price on top), then by type as tiebreaker
    const typeWeight: Record<string, number> = { order: 1, deal: 2, position: 3 };
    grouped.forEach(evts => {
      evts.sort((a, b) => {
        const priceDiff = b.price - a.price;
        if (priceDiff !== 0) return priceDiff;
        return (typeWeight[a.eType] || 0) - (typeWeight[b.eType] || 0);
      });
    });
    const markerTimes = Array.from(grouped.keys());
    interface BoundingBox {
      x1: number;
      x2: number;
      y1: number;
      y2: number;
    }

    const updateMarkerOverlays = () => {
      const lineContainer = container.querySelector(".marker-lines") as HTMLElement;
      if (!lineContainer) return;
      lineContainer.innerHTML = "";

      const placedBoxes: BoundingBox[] = [];

      const isOverlapping = (box: BoundingBox) => {
        // Add a tiny padding to the check
        const padX = 2;
        const padY = 0;
        return placedBoxes.some(
          b =>
            box.x1 - padX < b.x2 &&
            box.x2 + padX > b.x1 &&
            box.y1 - padY < b.y2 &&
            box.y2 + padY > b.y1
        );
      };

      for (const timeSec of markerTimes) {
        const x = chart.timeScale().timeToCoordinate(timeSec as UTCTimestamp);
        if (x === null) continue;

        // Vertical line (solid, matching MT5 style)
        const vlineColor = isDark ? "#666" : "#999";
        const line = document.createElement("div");
        line.style.cssText = `position:absolute;left:${x}px;top:0;bottom:0;width:1px;background:${vlineColor};pointer-events:none;`;
        lineContainer.appendChild(line);

        // Time label on x-axis (styled like crosshair axis label, hidden after drag)
        if (!timeLabelsHidden) {
          const d = new Date(timeSec * 1000);
          const axisLabelBg = isDark ? "#aaaaaa" : "#333333";
          const timeLabel = document.createElement("div");
          timeLabel.style.cssText = `position:absolute;left:${x}px;bottom:8px;transform:translateX(-50%);font-size:11px;color:#fff;background:${axisLabelBg};padding:4px 10px;border-radius:2px;white-space:nowrap;pointer-events:none;z-index:30;`;
          timeLabel.textContent = `${String(d.getUTCHours()).padStart(2, "0")}:${String(d.getUTCMinutes()).padStart(2, "0")}:${String(d.getUTCSeconds()).padStart(2, "0")}`;
          lineContainer.appendChild(timeLabel);

          // Also add the time label to placed boxes so we don't draw text over it
          placedBoxes.push({
            x1: x - 30,
            x2: x + 30,
            y1: container.clientHeight - 30,
            y2: container.clientHeight,
          });
        }

        const evts = grouped.get(timeSec) || [];
        const labelTextColor = isDark ? "#e0e0e0" : "#333";
        const textShadow = isDark ? "0 1px 3px rgba(0,0,0,0.8)" : "0 1px 3px rgba(255,255,255,0.9)";

        const eventsByPrice = new Map<number, EventLabel[]>();
        for (const evt of evts) {
          if (evt.lineOnly) continue;
          const p = evt.price;
          if (!eventsByPrice.has(p)) eventsByPrice.set(p, []);
          eventsByPrice.get(p)!.push(evt);
        }

        Array.from(eventsByPrice.entries()).forEach(([price, priceEvts]) => {
          const y = bidSeries.priceToCoordinate(price);
          if (y === null) return;

          const primaryEvt = priceEvts[0];

          let arrowColor = primaryEvt.isBuy ? "#2196f3" : "#ef5350"; // default: Buy=Blue, Sell=Red

          arrowColor = primaryEvt.isBuy ? "#ef5350" : "#2196f3";

          let arrowStyle = "";

          const entry = primaryEvt.entryType?.toUpperCase() || "IN";
          if (entry === "IN/OUT") {
            // Diamond shape (In/Out)
            arrowStyle = `width:10px;height:10px;background-color:${arrowColor};transform:translate(-50%,-50%) rotate(45deg);`;
          } else {
            if (primaryEvt.isBuy) {
              arrowStyle = `border-left:7px solid transparent;border-right:7px solid transparent;border-bottom:12px solid ${arrowColor};`;
            } else {
              arrowStyle = `border-left:7px solid transparent;border-right:7px solid transparent;border-top:12px solid ${arrowColor};`;
            }
          }

          // Draw ONE arrow for this price cluster
          const arrowEl = document.createElement("div");
          if (entry === "IN/OUT") {
            arrowEl.style.cssText =
              `position:absolute;left:${x}px;top:${y}px;pointer-events:none;z-index:20;` +
              arrowStyle;
          } else {
            arrowEl.style.cssText =
              `position:absolute;left:${x}px;top:${y}px;transform:translate(-50%,-50%);width:0;height:0;pointer-events:none;z-index:20;` +
              arrowStyle;
          }
          lineContainer.appendChild(arrowEl);

          let currentOffsetY = -6; // Start slightly above center so the first text aligns nicely with the arrow tip

          for (const evt of priceEvts) {
            const isSelected = evt.eType === entityType && evt.eId === entityId;
            const itemColor = evt.isBuy ? "#ef5350" : "#2196f3"; // match text color to its action

            const selectedStyle = isSelected
              ? `font-weight:700;color:${itemColor};font-size:12px;`
              : `font-weight:500;color:${labelTextColor};font-size:11px;`;

            const label = document.createElement("div");
            label.textContent = evt.text;

            const approxWidth = evt.text.length * 6.5;
            const height = 14;

            let attempts = 0;
            let finalYOffset = currentOffsetY;
            const finalXOffset = 10;

            while (attempts < 50) {
              const yPos = y + finalYOffset;
              const box: BoundingBox = {
                x1: x + finalXOffset,
                x2: x + finalXOffset + approxWidth,
                y1: yPos - height / 2,
                y2: yPos + height / 2,
              };

              if (!isOverlapping(box)) {
                placedBoxes.push(box);
                break;
              }

              if (finalYOffset < 36) {
                finalYOffset += 14;
              } else {
                const upAttempts = attempts - Math.floor(36 / 14);
                finalYOffset = -20 - upAttempts * 14;
              }
              attempts++;
            }

            label.style.cssText = `position:absolute;left:${x + finalXOffset}px;top:${y + finalYOffset}px;transform:translateY(-50%);white-space:nowrap;line-height:14px;text-shadow:${textShadow};pointer-events:none;z-index:20;${selectedStyle}`;
            lineContainer.appendChild(label);

            currentOffsetY += 14;
          }
        });
      }
    };
    chart.timeScale().subscribeVisibleLogicalRangeChange(updateMarkerOverlays);
    const rafUpdate = () => requestAnimationFrame(updateMarkerOverlays);
    container.addEventListener("mousemove", rafUpdate);
    container.addEventListener("wheel", rafUpdate);

    requestAnimationFrame(updateMarkerOverlays);

    chart
      .priceScale("right")
      .applyOptions({ autoScale: true, scaleMargins: { top: 0.1, bottom: 0.1 } });

    // Header: symbol + date range from ticks
    if (ticks.length > 0) {
      let minDateMs = Infinity;
      let maxDateMs = -Infinity;
      for (const t of ticks) {
        const ms = new Date(t.datetime).getTime();
        if (ms < minDateMs) minDateMs = ms;
        if (ms > maxDateMs) maxDateMs = ms;
      }
      const minDateStr = formatDateUTC(new Date(minDateMs));
      const maxDateStr = formatDateUTC(new Date(maxDateMs));
      setHeader(
        minDateStr === maxDateStr
          ? `${activePos?.symbol ?? ""} ${minDateStr}`
          : `${activePos?.symbol ?? ""} ${minDateStr} - ${maxDateStr}`
      );
    }

    if (events.length > 0 && bidData.length > 0) {
      // Find the event the user actually clicked on (entityType & entityId)
      const targetEvent = events.find(e => e.eType === entityType && e.eId === entityId);

      // If we found the target event, we center on it.
      // If not, we just fallback to the first event in the list.
      const centerTimeSec = targetEvent ? targetEvent.timeSec : events[0].timeSec;

      // Find its index in the bidData
      const centerIdx = bidData.findIndex(d => (d.time as number) >= centerTimeSec);

      if (centerIdx >= 0) {
        // Show 100 bars before and 100 bars after the event for a perfect "MT5 zoom" level
        const padding = 100;
        chart.timeScale().setVisibleLogicalRange({
          from: Math.max(0, centerIdx - padding),
          to: Math.min(bidData.length - 1, centerIdx + padding),
        });
      } else {
        chart.timeScale().fitContent();
      }
    } else {
      chart.timeScale().fitContent();
    }

    chart.subscribeCrosshairMove(param => {
      const tooltip = tooltipRef.current;
      if (!tooltip) return;
      if (!optionsRef.current.crosshair || !param.time || !param.point) {
        tooltip.style.display = "none";
        return;
      }
      const tick = tickByTime.get(param.time as number);
      if (!tick) {
        tooltip.style.display = "none";
        return;
      }

      const opts = optionsRef.current;
      const parts: string[] = [];
      if (opts.bidLine) parts.push(`<b>B</b> ${Number(tick.bid).toFixed(precision)}`);
      if (opts.askLine) parts.push(`<b>A</b> ${Number(tick.ask).toFixed(precision)}`);
      if (opts.lastLine && Number(tick.last) > 0)
        parts.push(`<b>L</b> ${Number(tick.last).toFixed(precision)}`);

      if (parts.length === 0) {
        tooltip.style.display = "none";
        return;
      }

      tooltip.style.display = "block";
      tooltip.style.left = `${param.point.x + 16}px`;
      tooltip.style.top = `${param.point.y - 28}px`;
      tooltip.innerHTML = parts.join("&ensp;");
    });

    return () => {
      container.removeEventListener("mousedown", onMouseDown);
      container.removeEventListener("mousemove", rafUpdate);
      container.removeEventListener("wheel", rafUpdate);
      chart.timeScale().unsubscribeVisibleLogicalRangeChange(updateMarkerOverlays);
      chart.remove();
      chartRef.current = null;
      bidSeriesRef.current = null;
      askSeriesRef.current = null;
      lastSeriesRef.current = null;
      // Clear manually-added DOM overlays
      const lineContainer = container.querySelector(".marker-lines") as HTMLElement | null;
      if (lineContainer) lineContainer.innerHTML = "";
      if (tooltipEl) tooltipEl.style.display = "none";
      setHeader("");
    };
  }, [
    serverId,
    treeData,
    entityType,
    entityId,
    ticks,
    isLoading,
    isDark,
    containerReady,
    theme.palette.background.paper,
  ]);

  const menuItems: { key: keyof typeof options; label: string; shortcut?: string }[] = [
    { key: "crosshair", label: "Crosshair", shortcut: "C" },
    { key: "bidLine", label: "Bid Line", shortcut: "B" },
    { key: "askLine", label: "Ask Line", shortcut: "A" },
    { key: "lastLine", label: "Last Line", shortcut: "L" },
    { key: "grid", label: "Grid", shortcut: "G" },
    { key: "priceLevels", label: "Price Levels" },
    { key: "timeMarks", label: "Time Marks" },
    { key: "autoVerticalScale", label: "Auto Vertical Scale" },
  ];

  return (
    <Box
      sx={{
        width: "100%",
        height: "100%",
        display: "flex",
        flexDirection: "column",
        borderRadius: 1,
        overflow: "hidden",
        position: "relative",
        pt: 1.5,
        pl: 1.5,
      }}
      onContextMenu={handleContextMenu}
    >
      {(isLoading || !treeData) && (
        <Box
          sx={{
            position: "absolute",
            inset: 0,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 20,
            bgcolor: isDark ? "rgba(0,0,0,0.4)" : "rgba(255,255,255,0.5)",
          }}
        >
          <Typography variant="body2" color="text.secondary">
            {!treeData ? "Loading tree data..." : "Loading ..."}
          </Typography>
        </Box>
      )}
      {!isLoading && ticks.length === 0 && (
        <Box
          sx={{
            position: "absolute",
            inset: 0,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 20,
          }}
        >
          <Typography variant="body2" color="text.secondary">
            No tick data available
          </Typography>
        </Box>
      )}
      <div
        ref={containerRef}
        style={{
          width: "100%",
          flex: 1,
          position: "relative",
        }}
      >
        {header && (
          <div
            style={{
              position: "absolute",
              top: 4,
              left: 6,
              fontSize: 11,
              color: isDark ? "#ccc" : "#555",
              zIndex: 3,
              pointerEvents: "none",
            }}
          >
            {header}
          </div>
        )}
        <div
          className="marker-lines"
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            bottom: 26,
            pointerEvents: "none",
            zIndex: 2,
          }}
        />
      </div>
      <div
        ref={tooltipRef}
        style={{
          display: "none",
          position: "absolute",
          pointerEvents: "none",
          background: isDark ? "rgba(20,20,20,0.95)" : "rgba(255,255,255,0.95)",
          border: `1px solid ${isDark ? "#444" : "#d0d0d0"}`,
          borderRadius: 4,
          padding: "4px 10px",
          fontSize: 12,
          fontFamily: "'JetBrains Mono', 'Fira Code', 'SF Mono', monospace",
          color: isDark ? "#e0e0e0" : "#333333",
          whiteSpace: "nowrap",
          zIndex: 10,
          boxShadow: isDark ? "0 2px 8px rgba(0,0,0,0.4)" : "0 2px 8px rgba(0,0,0,0.1)",
        }}
      />
      <Menu
        open={menuPos !== null}
        onClose={handleCloseMenu}
        anchorReference="anchorPosition"
        anchorPosition={menuPos ? { top: menuPos.y, left: menuPos.x } : undefined}
        slotProps={{ paper: { sx: { minWidth: 200 } } }}
      >
        {menuItems.map(item => (
          <MenuItem key={item.key} onClick={() => toggleOption(item.key)} dense>
            <ListItemIcon sx={{ minWidth: 28 }}>
              {options[item.key] && <MdCheck size={16} />}
            </ListItemIcon>
            <ListItemText>{item.label}</ListItemText>
            {item.shortcut && (
              <Typography variant="body2" color="text.secondary" sx={{ ml: 2 }}>
                {item.shortcut}
              </Typography>
            )}
          </MenuItem>
        ))}
      </Menu>
    </Box>
  );
}
